"""Typed mathematical dictionary, complete named-metaphor register, code inventory."""
from pathlib import Path
import json,ast,csv,re,hashlib
ROOT=Path(__file__).resolve().parents[2];D=ROOT/'3_Preuves_et_calculs/data';P=ROOT/'1_Presentation'
# id § level § name § symbol/formula § image § exact meaning/domain § composition guard
CORE=r'''
number§1§Nombre§x∈ℝ§Une place sur une règle.§Un réel sert de coordonnée ; les nombres complexes ajoutent une seconde coordonnée.§Une lettre peut changer de rôle ; son domaine doit être annoncé.
complex§1§Nombre complexe§z=a+ib, i²=−1§Une flèche qui va aussi vers le côté.§ℂ est un plan avec addition et multiplication ; Re z=a et Im z=b.§Complexe ne signifie ni positif ni négatif ; seul un réel peut recevoir cet ordre.
conjugate§1§Conjugaison§z̄=a−ib§La flèche se regarde dans un miroir.§Involution de ℂ ; dans un produit scalaire elle rend la norme réelle.§Oublier la conjugaison peut transformer une forme hermitienne en autre chose.
modulus§1§Module§|z|²=z̄z§La longueur de la flèche.§Quantité réelle non négative ; homogène au carré de l’amplitude.§La longueur oublie la phase, donc deux flèches différentes peuvent avoir le même module.
function§1§Fonction§f:X→Y§Une machine prend un jouet et rend un résultat.§À chaque entrée du domaine X correspond une sortie de Y.§Composer g et f exige que la sortie de f entre dans le domaine de g.
sum§1§Somme§Σ_k a_k§On rassemble des petites piles.§Somme finie ou limite de sommes partielles pour une série.§Une série infinie exige une règle de convergence ; réordonner peut changer une série conditionnelle.
integral§1§Intégrale§∫ f(x) dx§On rassemble toutes les fines bandes d’un dessin.§Intégrale de Lebesgue lorsque f est intégrable ; remplace une somme discrète.§Une intégrale impropre ne peut pas être manipulée sans vérifier sa convergence.
derivative§1§Dérivée§Df=f′§On regarde comment la pente change.§D est une dérivation, classique ou faible selon le domaine.§Df et f n’ont pas automatiquement les mêmes unités ; dx doit être typé.
second_derivative§1§Courbure§D²f=f″§On regarde si le chemin se courbe.§Deux dérivations ; définie classiquement pour C² ou faiblement dans H².§Un coin peut ajouter une distribution quand on prolonge une fonction par zéro.
partial§1§Dérivée partielle§∂_t F§On tourne un bouton en gardant les autres immobiles.§Dérivation selon une variable déclarée.§Une dérivée en temps physique est une puissance si la grandeur est une énergie ; un paramètre arithmétique n’est pas un temps physique.
support§1§Support§supp f⊂[−S,S]§L’endroit où le dessin n’est pas effacé.§Fermeture des points où la fonction est non nulle, au sens essentiel pour L².§Déplacer le dessin change son adresse, pas son diamètre.
limit§1§Limite§f_n→f§Les dessins se rapprochent de plus en plus.§Le sens dépend de la norme ou de la topologie annoncée.§Convergence ponctuelle, L² et H¹ ne sont pas interchangeables.
norm§1§Norme§||f||§Une règle qui mesure un dessin.§Positive, homogène, triangulaire ; la métrique choisie fixe ce que signifie proche.§Changer la règle conserve parfois le signe, pas les tailles ni les marges.
inner§1§Produit scalaire§⟨f,g⟩=∫f̄g§On mesure combien deux dessins se ressemblent.§Forme sesquilinéaire hermitienne ; ici convention antilinéaire en première variable.§Une métrique externe doit être définie sans présupposer le signe de Q_W.
composition§1§Composition§g∘f§Deux machines attachées l’une à l’autre.§Appliquer f puis g ; domaines et codomaines compatibles.§Le nom d’une machine ne suffit pas pour autoriser un passage.
units§1§Unités fictives§[f]=A, [Q]=E=A²§Chaque quantité porte une étiquette sur sa boîte.§x=log u est sans dimension ; A et E sont des unités formelles de tenue des calculs.§Une unité cohérente ne prouve pas un signe et ne donne pas une énergie physique.
exp§2§Exponentielle§e^x§Une taille qui se multiplie quand on ajoute un pas.§Fonction réelle positive ; e^(x+y)=e^x e^y ; extension entière sur ℂ.§e^z peut être complexe ; « exponentielle positive » concerne x réel.
log§2§Logarithme§x=log u§On compte les pas multiplicatifs avec une règle additive.§Inverse réel de exp sur u>0 ; log(uv)=log u+log v.§Le logarithme complexe demande un choix de branche.
sin_cos§2§Sinus et cosinus§e^(it)=cos t+i sin t§Une roue qui tourne.§Fonctions périodiques réelles ; décrivent les phases Fourier.§Une phase modifie les couplages si elle dépend de x.
sinh§2§Sinus hyperbolique§2 sinh(x/2)=e^(x/2)−e^(−x/2)§Deux tailles poussent en sens opposé.§Solution élémentaire utilisée pour l’inverse causal de D²−1/4.§Ce noyau inverse exige les deux moments pour refermer le support à droite.
gamma_fn§2§Fonction Gamma§Γ(s)=∫₀∞ t^(s−1)e^(−t)dt§Une machine prolonge la pile des factorielles.§Définie par l’intégrale pour Re s>0 puis prolongement méromorphe ; Γ(n+1)=n!.§Ses pôles et branches des facteurs associés doivent être pris en compte.
zeta§2§Fonction zêta§ζ(s)=Σₙ≥₁ n^(−s)§Une chorale où chaque entier chante.§Série absolument convergente pour Re s>1 ; prolongement méromorphe, pôle simple en 1.§La série brute n’est pas la définition convergente dans la bande critique.
xi§2§Zêta complétée§ξ(s)=½s(s−1)π^(−s/2)Γ(s/2)ζ(s)§On habille la chorale pour voir son miroir.§Fonction entière ; ξ(s)=ξ(1−s), zéros correspondant aux zéros non triviaux de ζ.§Symétrie ne suffit pas à imposer que tous les zéros soient sur l’axe.
rh§2§Hypothèse de Riemann§ζ(ρ)=0 ⇒ Re ρ=1/2, 0<Re ρ<1§Toutes les notes recherchées devraient rester sur une ligne.§Énoncé global sur tous les zéros non triviaux.§Un nombre fini de notes, matrices ou certificats ne couvre pas l’infini.
zero§2§Zéro et multiplicité§F(ρ)=0, F′(ρ)=0§Le dessin touche zéro ; parfois il s’y accroche deux fois.§Un zéro de multiplicité m annule les m premiers jets et pas le suivant.§Zéro double d’une fonction n’est pas automatiquement collision de branches suivies.
dirichlet§2§Série de Dirichlet§F(s)=Σ a_n n^(−s)§Chaque entier reçoit un volume de voix.§Fonction sur un demi-plan de convergence ; coefficients a_n déclarés.§Une équation fonctionnelle seule ne donne pas un produit d’Euler.
euler_product§2§Produit d’Euler§ζ(s)=∏ₚ(1−p^(−s))^(−1)§Les briques premières fabriquent les entiers.§Identité absolument convergente pour Re s>1.§La multiplicativité locale ne prouve pas RH.
von_mangoldt§2§Poids de von Mangoldt§Λ(p^m)=log p, Λ(n)=0 sinon§Seules les tours de briques premières portent une étiquette.§Fonction arithmétique ; −ζ′/ζ=ΣΛ(n)n^(−s) pour Re s>1.§Λ(n) ici n’est pas la constante de de Bruijn–Newman.
mobius§2§Fonction de Möbius§μ(n)=0 ou (−1)^r§On donne un signe aux sacs de briques sans doublon.§Nulle si un carré premier divise n ; sinon signe selon le nombre de facteurs premiers.§Une covariance de μ ne révèle pas chaque zéro.
character§2§Caractère de Dirichlet§χ(mn)=χ(m)χ(n)§Une couleur suit la règle de multiplication.§Caractère modulo q, périodique et nul sur les non-unités ; L(s,χ)=Σχ(n)n^(−s).§Ne pas identifier un mélange de fonctions L à un produit d’Euler.
li§2§Coefficients de Li§λ_n=Σρ[1−(1−1/ρ)^n]§On rassemble les notes dans une suite de balances.§Somme sur les zéros selon la convention symétrique ; critère global de Li pour ξ.§Sommes tronquées et intervalle fini de n ne prouvent pas toutes les inégalités.
heat§2§Flot de chaleur§∂_t H=−∂_x²H selon convention§On floute ou on accentue un dessin.§Flot de de Bruijn–Newman avec paramètre et signe déclarés, lié à un seuil de réalité des zéros.§Le paramètre n’est pas une température physique et la convention doit être fixée.
l2§3§Espace L²§∫|f|²<∞§Les dessins ont une taille totale finie.§Fonctions modulo égalité presque partout ; Hilbert avec norme quadratique.§La dérivée et la forme de Weil ne sont pas contrôlées par la seule norme L².
h1§3§Espace H¹§||f||H¹²=||f||₂²+||f′||₂²§La règle mesure aussi les pentes.§Fonctions L² avec dérivée faible L².§Sa positivité est externe ; un opérateur compact peut avoir une forme positive sans marge uniforme.
h03§3§Espace H₀³§ψ,ψ′,ψ″=0 aux bords§Le dessin et ses deux premières pentes s’attachent au bord.§Fermeture de Cc∞(−S,S) dans H³ ; traces nulles jusqu’à l’ordre 2.§La définition dépend du domaine ouvert et du prolongement par zéro.
smooth§3§Cœur lisse§Cc∞(−S,S)§Des dessins sans coins, rangés loin du bord.§Fonctions infiniment dérivables à support compact intérieur.§Une fonction polynomiale coupée au bord n’est généralement pas dans ce cœur.
translation§3§Translation§U_a f(x)=f(x−a)§La valise change d’adresse sans changer son contenu.§Unitaire dans L² et H¹ sur ℝ ; mêmes autocorrélations.§E_S est transporté dans une fenêtre plus grande, pas forcément dans la même E_S.
dilation_nb§3§Dilatation Beurling§D_a f(t)=a^(−1/2)f(t/a)1_(0,a)(t)§Le dessin tient dans une boîte plus petite.§Isométrie L²(0,1) pour 0<a≤1 ; sous J elle devient translation.§Le facteur a^(−1/2) est nécessaire et les domaines ne sont pas celui de U sans J.
beurling_func§3§Fraction Beurling§ρ_θ(t)={θ/t}, Σc_jθ_j=0§On garde le petit reste d’un partage.§Combinaisons de parties fractionnaires dans L²(0,1), condition admissible de Nyman–Beurling.§Leur densité est un critère de RH, donc ne peut pas être supposée pour prouver RH.
jmap§3§Passage logarithmique J§Jf(x)=e^(−x/2)f(e^(−x))§Une règle courbe devient une règle droite.§Unitaire L²(0,1)→L²(0,∞) ; change la mesure avec son facteur.§L² ne devient pas H¹ par simple changement de coordonnées.
logmap§3§Passage multiplicatif§ℒf(u)=u^(−1/2)f(log u)§Des pas deviennent des multiplications.§Unitaire L²(ℝ,dx)→L²(ℝ₊,du).§Ne pas confondre ℒ avec J, qui utilise x=−log t et une demi-droite.
fourier§3§Transformée de Fourier§f̂(τ)=(2π)^(−1/2)∫f(x)e^(−iτx)dx§On entend les rythmes cachés dans le dessin.§Unitaire L² par Plancherel ; translations deviennent phases, D devient iτ.§Une convention de normalisation différente change les constantes.
mellin§3§Transformée de Mellin§Mf(s)=∫₀∞ f(u)u^(s−1)du§On entend les rythmes de changements de taille.§Pour ℒf, Mℒf(s)=∫f(x)e^((s−1/2)x)dx ; entier si support compact.§Les moments admissibles sont les valeurs en 0 et 1, pas toute la transformée.
convolution§3§Convolution§(η*f)(x)=∫η(x−y)f(y)dy§Un petit pinceau passe sur le dessin.§Lissage et produit Fourier selon convention ; support s’additionne.§Lisser peut déborder de la fenêtre ; il faut une marge ou un cutoff.
mollifier§3§Mollificateur§η_δ(x)=δ^(−1)η(x/δ), ∫η=1§Un pinceau de largeur δ.§Approximation de l’identité ; η lisse à support compact.§Un contrôle en H¹ ou dans la métrique R doit être prouvé, pas déduit de L² seul.
cutoff§3§Fonction de coupure§χ f§On efface doucement l’extérieur d’une boîte.§χ∈Cc∞, bornes de dérivées déclarées ; multiplicateur local.§Les dérivées de χ ajoutent des termes au budget.
moments§3§Deux moments§ℓ±(f)=∫f(x)e^(±x/2)dx§Deux balances doivent être à zéro.§Fonctionnelles linéaires continues à support fixé.§Elles ne sont ni l’intégrale seule ni une condition de signe.
admissible§3§Espace admissible E_S§E_S=H₀¹(−S,S)∩kerℓ₊∩kerℓ₋§Les dessins passent deux portes et restent dans la boîte.§Espace fermé de codimension 2 ; domaine H¹ de la forme complète.§Changer la fenêtre ou la norme impose un nouveau contrat.
p_operator§3§Moule admissible P§P=D²−1/4§Un moule ferme les deux ouvertures.§Isomorphisme H₀³(−S,S)→E_S ; annulations exactes par intégration par parties.§P impose les moments, pas le signe de Q_W. Ce P n’est pas un polynôme zêta.
p_inverse§3§Inverse du moule§ψ(x)=∫₋Sˣ 2sinh((x−y)/2)f(y)dy§On retrouve le dessin avant le moule.§Inverse de P pour f∈E_S, deux moments ferment les traces à droite.§Sans ces moments, le résultat ne reste pas dans H₀³.
seed§3§Graine polynomiale§ψS,k=(1−x²/S²)^4(x/S)^k 1_[−S,S]§Une pâte qui colle bien aux bords.§Graine H₀⁴, C³ sur ℝ ; fS,k=PψS,k∈H₀² ; famille indépendante et dense dans E_S.§Pas C∞ en général ; la continuité H¹ de Q justifie son usage.
modulation§3§Modulation§M_τ f=e^(iτx)f§On ajoute une rotation à chaque place.§Unitaire L² ; déplace la fréquence Fourier.§Brise généralement les deux moments ; P M_τ ψ reste admissible mais change Q.
adjoint§4§Adjoint§⟨Af,g⟩=⟨f,A*g⟩§La machine se regarde dans la bonne balance.§Opérateur adjoint relativement aux domaines et à la métrique déclarés.§A* dépend du produit scalaire ; les opérateurs non bornés exigent leur domaine.
correlation§4§Corrélation§h_ij(t)=∫f_i(y)f̄_j(y−t)dy§On glisse deux dessins pour voir où ils se recouvrent.§Corrélation croisée ; h_ij(−t)=conj h_ji(t).§Une corrélation croisée pair/impair peut être non nulle.
symcorr§4§Corrélation symétrisée§H_ij=(h_ij+h_ji)/2 pour tests réels§Deux glissements opposés partagent la balance.§La partie réelle symétrique gouverne les matrices réelles de Q_W.§Seule cette symétrisation s’annule entre parités opposées.
polarization§4§Polarisation§q(f,g) reconstruit depuis Q(f)§On ouvre une balance pour voir les attaches entre jouets.§Identité de polarisation d’une forme quadratique hermitienne.§Le couplage est indispensable ; des diagonales positives ne suffisent pas.
weil_q§4§Forme complète de Weil§Q_W=E_arch−C₀||f||₂²−Q_pr§Une balance compte tous ses plateaux.§E_arch=∫₀∞w(x)||U_xf−f||₂²dx, C₀=log(8π)+γ_E+π/2 ; Q_pr=2Σ Λ(n)n^(−1/2)Re h_f(log n).§Toujours utiliser la partie archimédienne ET les premiers ; le signe global reste ouvert.
arch_kernel§4§Noyau archimédien§w(x)=e^(−x/2)/(1−e^(−2x))§Les petits déplacements pèsent plus lourd.§Positif pour x>0 ; ~1/(2x) près de 0, décroît à l’infini.§Sa singularité exige un contrôle de U_x f−f.
prime_form§4§Forme des premiers§Q_pr=2Σₚ,m log p·p^(−m/2)Re h_f(m log p)§Les tours premières mettent des poids sur la balance.§Somme finie à support de diamètre D : p^m≤e^D.§Chaque corrélation peut changer de signe ; cette partie n’est pas positive en général.
external_r§4§Métrique logarithmique R§R(f)=||f||₂²+E_arch(f)§On mesure la taille et les petits glissements.§Forme positive fermée de multiplicateur 1+a(τ), indépendante des premiers et de RH.§Domaine X_S plus large que H¹ ; le Riesz change quand on change de métrique.
a_multiplier§4§Poids logarithmique a§a(τ)=2Σₙ≥₀ τ²/[β_n(β_n²+τ²)], β_n=2n+1/2§Les rythmes rapides finissent par peser lourd.§Positif, monotone en |τ|, tend vers l’infini ; multiplicateur de E_arch.§Il contrôle une queue fréquentielle, pas le signe arithmétique à lui seul.
x_domain§4§Domaine logarithmique X_S§supp f⊂[−S,S], R(f)<∞, ℓ±f=0§Une boîte dont la règle surveille les glissements.§Hilbert avec métrique R ; cœur admissible Cc∞ dense ; injection compacte dans L².§La compactité vaut à S fixé ; ses constantes ne sont pas uniformes en S.
riesz_h1§4§Riesz dans H¹§Q_W(f,g)=⟨T_Sf,g⟩H¹§La balance devient une machine sur les dessins.§T_S signé, borné, autoadjoint et compact sur E_S.§Aucune marge c>0 dans H¹ sur tout E_S, même si la forme est positive.
riesz_r§4§Riesz dans R§Q_W(f,g)=⟨(I−K_S)f,g⟩R§Le même dessin est l’identité moins une correction.§K_S compact autoadjoint sur X_S ; finitement de directions négatives à S fixé.§Cela ne dit pas que leur nombre est zéro.
compact§4§Opérateur compact§A(ball) relativement compact§Beaucoup de dessins tiennent dans quelques petites boîtes.§Les images de suites bornées ont des sous-suites convergentes.§Compact ne signifie pas positif ; ses valeurs propres peuvent s’approcher de zéro.
coercivity§4§Coercivité§Q(f)≥c||f||², c>0§La balance garde toujours une marge minimale.§Minoration uniforme dans une métrique donnée.§La positivité Q≥0 est plus faible ; la marge H¹ uniforme est exclue ici.
gram§4§Matrice de Gram§B_ij=⟨f_i,f_j⟩H¹§Une table dit comment les dessins se chevauchent.§B positive définie pour une famille indépendante ; ici rationnelle exacte.§B ne doit pas être identifiée à G_W, la forme dont le signe est recherché.
compression§4§Compression de Weil§(G_W)_ij=Q_W(f_i,f_j)§On prend une petite fenêtre dans une grande balance.§Matrice hermitienne finie sur un sous-espace admissible.§Un résultat fini ne vaut que sur ce sous-espace.
pencil§4§Paire de matrices§G_Wv=λBv§Deux balances suivent les mêmes coordonnées.§Problème spectral généralisé avec B>0.§Transformer G_W exige de transformer B simultanément.
congruence§4§Changement de base§G↦C*GC, B↦C*BC§On renomme les pièces du puzzle.§C inversible ; inertie de G et spectre généralisé du couple conservés.§Entrées, valeurs propres ordinaires et pivots ne sont pas tous conservés.
cholesky§4§Cholesky§B=LL*§On remet la règle de mesure à plat.§Factorisation pour B hermitienne positive définie ; normalise la paire.§Une base très mal conditionnée demande une précision contrôlée.
eigen§4§Valeur propre§Av=λv§Un dessin ressort dans sa propre direction.§λ indique la dilatation sur une direction ; pour hermitien λ réel.§Une valeur calculée sans intervalle d’erreur reste numérique.
inertia§4§Inertie§(n₊,n₋,n₀)§On compte les directions qui montent, descendent ou restent à zéro.§Signature d’une forme hermitienne ; invariante sous congruence inversible.§Le nombre de directions négatives fini n’est pas leur absence.
parity§4§Parité§f(−x)=±f(x)§Deux dessins : miroir pareil ou miroir opposé.§Q_W et les métriques respectent la réflexion ; blocs pair/impair découplés.§Un changement de base mêlant ces secteurs peut créer des entrées croisées.
schur§4§Complément de Schur§δ=a−c*G^(−1)c§Le nouveau jouet tire sur les attaches des anciens.§Si G>0, δ est le minimum résiduel ; sinon identité algébrique sous inversibilité.§Si G est singulière positive, il faut c∈Ran G et G†.
pseudoinverse§4§Pseudo-inverse§G†§La machine inverse ce qu’elle sait voir.§Inverse sur les valeurs propres non nulles, zéro sur le noyau.§Ne répare pas un couplage hors de l’image.
flag§4§Drapeau de sous-espaces§V₁⊂V₂⊂…§On ouvre des boîtes dans un ordre choisi.§Une chaîne fixe sert à définir les dettes successives.§Changer l’ordre change les pivots ; l’invariant de dette exige le même drapeau.
schur_ratio§4§Dette normalisée§δ_G/δ_B§La nouvelle charge est mesurée avec la même règle.§Invariant sous changement de base ancien et v↦αv+w ancien, pour drapeau fixé et inverses valides.§Ce quotient n’est pas invariant sous changement arbitraire du drapeau.
tail§5§Queue de l’opérateur§||K_S|V⊥||<1§Les jouets restants ne peuvent plus faire basculer seuls la balance.§Un V fini existe par compactité ; obtenir une borne effective reste une obligation.§L’existence de V ne donne pas son indice ni un certificat calculable.
finite_reduction§5§Réduction par queue et Schur§G_eff=G₀₀−G₀₁G₁₁^(−1)G₁₀§On range l’infini et l’on garde ses attaches exactes.§Si le bloc de queue est uniformément positif, signe global équivalent au Schur fini.§Une compression finie positive sans borne de queue ne suffit pas.
density§5§Densité d’une famille§closure(∪V_n)=E_S§Les petits dessins peuvent approcher tous les dessins.§Ici densité de P[w_S·polynômes] dans H¹ ; puis dans X_S par le cœur.§Dense ne signifie pas que le signe est positif sur cette famille.
all_indices§5§Quantificateur global§∀S>0, ∀n≥1§Chaque boîte et chaque taille doivent être couvertes.§Une preuve globale exige tous les supports et tous les tests via cœur et continuité.§Une extension de plafond couvre quelques indices supplémentaires seulement.
bellman§5§Bellman des contrats§V(s)=max_a E[r(s,a)+γV(s′)]§On choisit un coup qui ouvre plusieurs portes.§s porte objets, obligations et preuves ; actions ont résultats conditionnels et coûts ; ici horizon fini γ=1.§Le score de recherche n’est ni une probabilité de RH ni la forme de Weil.
and_or§5§Portes ET et OU§ET: tous ; OU: un chemin valide§Deux clés pour une porte, ou deux portes possibles.§Graphe d’obligations avec complémentarités ; utile pour les coups doubles.§Une flèche logique est autorisée seulement si son contrat est prouvé.
jet§5§Jet§J^mF(z)=(F,F′,…,F^(m))(z)§On garde le dessin, la pente et les courbures.§Données locales jusqu’à un ordre fini.§Un jet local n’indique pas à lui seul la branche globale suivie.
branch§5§Branche§F(z,t)=0, z=z(t)§Un chemin local à travers une forêt.§Si ∂_zF≠0, fonction implicite locale ; près d’un zéro multiple il faut un autre modèle.§Continuer à travers une collision nécessite conditions et choix ; sujet encore ouvert du corpus.
collision§5§Collision de zéros§F=∂_zF=0§Deux chemins se touchent.§Système local de dégénérescence ; jets, discriminant ou préparation locale à spécifier.§Une collision certifiée locale ne contrôle pas tous les passages globaux.
discriminant§5§Discriminant§Disc(P)=0§Une alarme quand deux racines se rejoignent.§Pour un polynôme, détecte racines multiples ; extension locale à préciser.§Ne pas appliquer la formule polynomiale directement à une fonction entière quelconque.
complex_A§5§Coefficient complexe A§A∈ℂ§Une flèche peut tourner et grandir.§Paramètre de certaines familles du corpus ; |A|²≥0, mais les termes croisés gardent la phase.§Un argument limité à A réel positif ne couvre pas A complexe arbitraire.
weyl_trace§5§Trace et correspondances de Weil§σ(ξξ′)>0 dans le cadre géométrique§Une règle relie les allers et les retours.§Positivité des correspondances dans la preuve sur les courbes sur corps finis ; source Wei48.§Aucun transfert de cette géométrie à ζ des entiers n’est démontré.
frobenius§5§Frobenius§Frob:x↦x^q§On répète un geste exact dans un monde fini.§Morphisme en caractéristique p ; action cohomologique avec trace dans le cadre approprié.§Un opérateur virtuel aux mêmes valeurs propres n’est pas automatiquement un morphisme.
rr§5§Riemann–Roch§ℓ(D)−ℓ(K−D)=deg D+1−g§On compte les dessins autorisés et les contraintes.§Théorème pour un diviseur sur une courbe lisse projective ; géométrie nécessaire.§Un bilan formel de dimensions ne construit pas une courbe pour ζ.
gap§5§Marge spectrale§inf spec(A)§On cherche le plus petit espace sous la balance.§Dépend de l’opérateur et de sa métrique ; existence ou borne certifiée à distinguer.§La marge R éventuelle peut dépendre de S ; la marge H¹ strictement positive est impossible ici.
certificate§5§Certificat§borne d’erreur + décision§On garde une règle qui encadre le résultat.§Calcul rationnel exact ou intervalle validé et toutes conditions contrôlées.§Deux précisions concordantes ne remplacent pas une borne d’erreur.
interval§5§Calcul par intervalles§x∈[a,b]§Le résultat habite une petite boîte fermée.§Arithmétique à arrondi dirigé et propagation rigoureuse des inclusions.§Une valeur à beaucoup de chiffres n’est pas un intervalle validé.
stability§5§Stabilité d’un signe§|erreur|<marge§La balance ne bascule pas malgré une petite secousse.§Perturbation contrôlée d’une forme ou d’un spectre.§Le couplage et le conditionnement amplifient l’erreur ; il faut les borner.
invariant§5§Invariant symbolique§I(Tx)=I(x)§Un signe survit à la traduction.§Une quantité conservée par une transformation définie avec ses conditions.§Un même symbole écrit deux fois n’est pas un invariant.
relational§5§Invariant relationnel§R(x,y)⇒R(Tx,Ty)§Les attaches survivent même si les pièces changent.§Moments nuls, incidence de sous-espaces, congruence simultanée, ordre d’un drapeau.§Une relation peut être conservée sans conserver les valeurs numériques.
grammar§5§Grammaire des passages§objet : domaine → codomaine ; garde ; coût§Les mots savent quelles phrases ils peuvent former.§Contrat de traduction typé, preuve et perte séparées ; validateur programmé.§La validation vérifie le contrat codé, pas une preuve automatique de toutes les mathématiques.
utility§5§Utilité de recherche§U_decision≠U_a§On compte les portes réellement ouvertes.§Choix éditorial de gains sur obligations ; aucune unité physique.§Ne pas confondre U_decision avec la translation U_a.
g_symbols§5§Les différents G§G_log(s), G_NB, G_W, B§Quatre boîtes ne portent plus la même étiquette.§G_log désigne un logarithme local selon le document ; G_NB un Gram ; G_W une compression ; B la métrique externe.§La désambiguïsation exige le document ; le symbole G seul ne donne pas le domaine.
d_symbols§5§Les différents D§D_x, D_mult, D_Frob§Trois gestes portent des noms complets.§D_x dérive ; D_mult mesure un défaut multiplicatif ; un logarithme de Frobenius exige une branche et un domaine.§Ne pas composer ces symboles comme s’ils étaient la même machine.
projector§5§Projection§Π_V f§On garde la partie qui entre dans une boîte.§Projection orthogonale dans une métrique annoncée ; Π_V²=Π_V.§Ce P/Π n’est pas le moule D²−1/4 ; projection H¹ et projection R diffèrent.
polynomial§5§Polynôme§P_poly(u)=Σc_k u^k§Un dessin fabriqué par quelques briques de puissances.§Fonction algébrique de variable déclarée ; zêta polynomiale en corps fini selon le contexte.§Ce P n’est pas l’opérateur différentiel.
li_kappa§5§Les différentes κ§κ_Li, κ_pli§Deux petites étiquettes doivent garder leur boîte.§Coefficient ou paramètre selon le document ; définition locale obligatoire.§Aucune égalité entre les κ n’est fournie par leur seule lettre.
tonelli§5§Tonelli et échange positif§∫Σ f_n=Σ∫f_n si f_n≥0§On compte les mêmes briques dans deux ordres.§Autorise l’échange pour fonctions mesurables non négatives, même si valeur infinie.§Pour des termes signés, il faut d’autres hypothèses de domination/convergence.
plancherel§5§Plancherel§||f||₂=||f̂||₂§La même chanson a la même taille sur deux portées.§Isométrie Fourier L² avec normalisation unitaire.§L’égalité L² seule ne donne pas les domaines des formes plus fortes.
commutator§5§Commutateur§[P,M_τ]=M_τ(2iτD−τ²)§Deux gestes changent selon leur ordre.§P M_τψ=M_τ(Pψ+2iτψ′−τ²ψ).§Il explique pourquoi moduler la graine puis appliquer P n’est pas moduler le test seul.
regularizer§5§Pont régularisé§T=P[χ(η_δ*Γ_Sg)]§On déplace, lisse, range et passe dans le moule.§Γ_S est le décalage de l’entrée prolongée par zéro ; sortie admissible ; coût δ^(−3) en H¹ sous cutoffs fixés.§Le coût et les limites doivent être uniformisés avant de conclure globalement.
mom_correction§5§Correction des moments§f↦f−aφ−bφ′§Deux petites retouches remettent les balances à zéro.§Matrice des moments de φ et φ′ inversible pour φ paire non nulle positive ; correction continue.§Il faut un support intérieur commun et des coefficients calculés, pas une correction abstraite gratuite.
power§1§Puissance par dérivation§dE/dt§On mesure combien la pile change à chaque tic.§Si t est un temps, unité E/T ; si t est un indice arithmétique, unité formelle différente.§E≥0 n’impose pas dE/dt≥0 ; par exemple E(t)=e^(−t)>0 et E′<0.
entropy§2§Entropie et conventions§H(p)=−Σp_i log p_i§On compte combien un choix nous surprend.§Entropie de Shannon non négative pour une loi discrète ; entropie différentielle peut être négative.§Il n’existe pas une positivité universelle de toute quantité appelée entropie.
energy§1§Énergie arithmétique formelle§E_ar=Q_W(f)§La balance porte l’étiquette énergie.§Unité fictive A² pour une forme quadratique ; changement d’amplitude c multiplie par |c|².§Le nom énergie ne donne pas Q_W≥0 : c’est précisément le signe recherché.
phase§3§Phase constante§f↦e^(iθ)f§Tout le dessin tourne du même angle.§Moments nuls, autocorrélation, R et Q_W conservés.§Une phase variable e^(iτx) est une autre opération.
scaling_support§3§Changement d’échelle§f(x)↦f(x/S)§On agrandit la boîte et le dessin.§Le support et les dérivées changent ; P et les points log(p^m) ne se transportent pas inchangés.§Ce changement n’est pas une invariance de Q_W.
range§4§Image et noyau§Ran G, ker G§Ce que la machine peut produire, et ce qu’elle efface.§Sous-espaces ; pour G hermitienne finie, Ran G=(ker G)⊥.§Dans Schur singulier, c hors de Ran G crée une direction négative.
gamma_discount§5§Rabais Bellman γ§0≤γ≤1§Les coups éloignés peuvent peser moins lourd.§Paramètre de décision, ici γ=1 à horizon fini pour les contrats.§γ_decision n’est ni Γ fonction spéciale ni γ_E constante d’Euler.
euler_constant§2§Constante d’Euler§γ_E=lim(Σₖ≤n1/k−log n)§Une petite correction reste après deux grands comptes.§Constante réelle présente dans C₀.§Ne pas l’identifier au rabais γ de Bellman.
determinant§4§Déterminant§det G§On mesure si un puzzle aplati perd une direction.§Produit des valeurs propres en dimension finie ; zéro si matrice singulière.§Un déterminant positif seul ne garantit pas une forme positive.
ldl§4§Décomposition LDL*§G=LDL*§On ouvre la balance pivot par pivot.§Factorisation avec pivotage adapté ; D porte l’inertie.§Les petits pivots et les permutations doivent être contrôlés ; ils dépendent du drapeau.
minmax§5§Principe variationnel§λ_min=inf Q(f)/R(f)§On cherche le dessin qui fait descendre le plus la balance.§Quotient de Rayleigh dans la métrique annoncée ; restriction finie donne un diagnostic.§Une infimum sur un petit sous-espace peut manquer une direction négative ailleurs.
epsilon_family§5§Erreur de famille§G_n≥−ε_n B_n, ε_n→0§Les petites dettes disparaissent dans toutes les boîtes.§Avec famille imbriquée dense et continuité, cette borne pour tout n implique Q_W≥0.§Une suite de bornes non certifiées ou sans tous les n ne remplit pas le contrat.
bilinear_defect§5§Défaut de transport§|q(Tf,Tg)−q(f,g)|§On mesure ce qu’une traduction abîme.§Différence de formes sur domaines compatibles, bornée par normes et erreurs de T.§Une transformation non isométrique exige cette comptabilité.
negative_index§5§Indice négatif§ind₋(Q)§Combien de directions font pencher vers le bas.§Dimension maximale d’un sous-espace où Q<0 ; finie à S fixé via I−compact.§Fini ne signifie pas zéro et ne couvre pas tous les supports.
band_projector§5§Projection fréquentielle§Π_T=ℱ^(−1)1_[−T,T]ℱ§On écoute seulement les rythmes assez lents.§Projection orthogonale L² ; queue contrôlée par 1+a(T) dans R.§Elle ne conserve pas le support compact ni les moments ; c’est un outil d’estimation, pas un test admissible automatique.
window_time§5§Support et temps logarithmique§x=log u, D=diam supp f§On transforme les tailles en positions.§Nombre de premiers en jeu lié à e^D ; support centré n’est qu’une convention.§Ne pas identifier ce x à un temps physique ni réduire le diamètre à la position du centre.
hamrigid§5§Rigidité de Hamburger§équation fonctionnelle + série + croissance§Les règles complètes forcent une chanson précise.§Dans le cadre Ham21, les hypothèses complètes imposent F=cζ ; voir source corrigée document 67.§L’équation fonctionnelle isolée ne suffit pas.
counterexample§5§Contre-exemple local§∃x : propriété fausse§Un seul jouet peut montrer qu’une règle casse.§Réfute la proposition avec ses hypothèses exactes ; un témoin numérique demande une certification.§Fermer un candidat ne ferme pas RH ni toutes les autres routes.
certificate_cutoff§4§Plafond premier exact§X=⌊e^(2S)⌋§On ferme la liste de briques sans en oublier une.§Encadrement rationnel Taylor inférieur/supérieur avec même partie entière.§Le plafond exact ne certifie pas les poids logarithmiques ni la quadrature archimédienne.
state§5§État épistémique§s=(objets, preuves, obligations)§La carte garde ce qui a été construit.§État du protocole, résultats et limites, horodatage avant les expériences.§Un résultat appris ensuite ne doit pas être présenté comme une prévision préalable.
double_gain§5§Coup double§action→deux contrats vérifiés§Une clé ouvre deux portes liées.§Ici P : moments+norme ; parité : réduction+contre-épreuve ; R : domaine+queue finie.§Deux noms nouveaux ne comptent pas comme deux preuves.
hermitian§4§Forme hermitienne§q(g,f)=conj q(f,g)§Le miroir répond dans l’autre sens.§Garantit Q(f)=q(f,f) réel ; symétrie de la forme complète.§Réel ne signifie pas positif.
weak_derivative§3§Dérivée faible§∫fφ′=−∫gφ§La pente est reconnue par de petits dessins tests.§g est la dérivée distributionnelle de f lorsqu’elle appartient à l’espace exigé.§La pente classique peut manquer aux coins ; les traces restent importantes.
trace_boundary§3§Trace au bord§f(±S), f′(±S),…§Le bord garde les attaches du dessin.§Valeurs limites définies pour les Sobolev suffisamment réguliers en dimension un.§Un prolongement par zéro sans traces nulles peut créer des masses de Dirac.
schwartz§3§Espace de Schwartz§sup |x^mD^nf(x)|<∞§Le dessin et ses pentes s’effacent très vite.§Fonctions lisses à décroissance rapide, cœur fréquentiel pour les approximations.§Décroissance rapide n’est pas support compact.
functional_equation§2§Équation fonctionnelle§ξ(s)=ξ(1−s)§La chorale se répond dans un miroir.§Symétrie analytique exacte de la fonction complétée.§Le miroir permet des paires hors de la ligne ; il ne force pas RH seul.
nbcriterion§5§Critère Nyman–Beurling§1∈closure span{ρ_θ avec moments}§Approcher un dessin simple suffit dans le bon monde.§Équivalence à RH sous l’énoncé et la norme exacts de Beurling ; voir document 67.§La densité de toute entrée L² après régularisation n’est pas la densité des entrées NB.
real_positive§1§Positivité§x≥0 ; Q(f)≥0§La balance ne descend pas sous sa marque.§Ordre sur les réels ; positivité d’une forme pour toutes les entrées du domaine.§Produit de nombres positifs positif ; une somme signée ou une dérivée n’hérite pas de cette règle.
operator_norm§4§Norme d’opérateur§||A||=sup_||f||=1||Af||§Le plus grand agrandissement possible.§Dépend des normes de départ et d’arrivée ; contrôlée par une borne effective.§Une petite entrée matricielle ne donne pas une petite norme globale sans estimation.
projection_error§5§Erreur d’approximation§||(I−Π_N)j_S||§Les petites boîtes manquent encore une partie du dessin.§Norme de l’injection compacte après projection finie dans la métrique cible.§Existence d’une limite zéro ne fournit pas son taux certifié.
matrix_l2_bound§5§Budget arithmétique L²§M_S=C₀+1+2Σₚᵐ≤e²ˢ log p·p^(−m/2)§On compte tout le poids qui peut tirer la balance.§Borne de |(C₀+1)⟨f,g⟩+q_pr(f,g)|≤M_S||f||||g||.§Budget valable à S fixé, croît avec le support ; ne donne pas le signe.
schur_tail_gate§5§Porte de queue positive§||j_S|V⊥||² M_S<1§Les jouets restants ne tirent plus assez fort.§Implique Q≥(1−M_Sη²)R sur V⊥ ; couplages avec V encore à traiter.§Queue positive seule ne rend pas la tête positive ; le Schur complet demeure nécessaire.
measure_change§3§Changement de mesure§dt=e^(−x)dx§La règle change l’épaisseur des bandes.§Le facteur racine dans J et ℒ conserve les normes L².§Oublier la racine du jacobien détruit l’isométrie.
and_obligation§5§Obligation globale de signe§∀S, G_eff,S⪰0§Toutes les dernières balances doivent tenir.§Après queue certifiée, résoudre le Schur fini pour chaque S, ou une loi uniforme couvrante.§Ni l’existence du Schur ni les expériences finies n’acquittent cette obligation.
resolvent§5§Résolvante§(A−zI)^(−1)§On cherche comment une machine répond à une sollicitation.§Définie pour z hors du spectre avec domaines fixés ; utile au contrôle de queue.§Une résolvante postulée sans exclusion spectrale est circulaire.
spectral_essential§5§Spectre essentiel§spec_ess(I−K)={1}§La grande foule des rythmes reste autour d’un.§Pour K compact autoadjoint sur un Hilbert infini ; seules exceptions discrètes ailleurs.§Cela autorise des valeurs négatives isolées ; aucun signe global automatique.
rayleigh_units§4§Quotient sans dimension§Q(f)/B(f)§Deux piles avec la même étiquette peuvent être comparées.§Q et B portent unité A² ; leur quotient est sans dimension dans les unités formelles.§Sa valeur dépend de la métrique B ; comparer H¹ à R exige le signaler.
product_rule§1§Règle du produit§D(fg)=f′g+fg′§Deux dessins bougent, il faut compter deux effets.§Identité de Leibniz sous régularité suffisante.§Les cutoffs et les phases apportent donc des termes supplémentaires.
inequality_cs§1§Cauchy–Schwarz§|⟨f,g⟩|≤||f||||g||§L’attache de deux dessins ne dépasse pas leurs tailles.§Inégalité Hilbert, utilisée pour majorer corrélations et primes.§La majoration de taille ne décide pas du signe de l’attache.
identity§1§Identité§If=f§Le jouet revient pareil.§Opérateur neutre dans le domaine choisi.§Dans I−K, la présence de I ne prouve pas que K≤I.
inclusion§3§Injection j_S§j_S:X_S→L²§On range un dessin dans une boîte plus large.§Application identité sur les fonctions mais changement de norme ; compacte à S fixé.§Même fonction ne signifie pas même topologie.
defect_multiplicative§5§Défaut multiplicatif§Δ_F(m,n)=a(mn)−a(m)a(n)§Les briques révèlent si la règle de montage tient.§Observable arithmétique de fermeture, avec indices et coefficients déclarés.§Annuler ce défaut ne donne pas le signe de la forme globale.
floor§1§Partie entière§⌊x⌋§On garde seulement les piles entières.§Plus grand entier ≤x ; détermine le plafond discret des puissances premières.§Près d’un entier, il faut encadrer x avant de décider.
factorial§2§Factorielle§n!=1·2·…·n§On compte tous les rangements de n jouets.§Fonction sur les entiers non négatifs, 0!=1 ; intervient dans Taylor.§Une série Taylor tronquée exige une borne de reste.
tail_taylor§4§Reste de Taylor positif§e^x=Σₖ≤N x^k/k!+reste§On compte les petites piles encore oubliées.§Pour x≥0, termes positifs et borne géométrique si x<N+2.§Le reste rationnel n’est pas une certification de toutes les autres fonctions transcendantes.
complex_inner§4§Calcul complexe des formes§Q(Σc_i f_i)=c*G c§Chaque flèche tire sur toutes les autres.§Une base réelle avec matrice réelle symétrique se complexifie hermitiennement ; critère PSD identique.§Cela couvre les combinaisons complexes de cette famille, pas tout paramètre A d’autres constructions du corpus.
bandwidth§5§Largeur fréquentielle T§|τ|≤T§On écoute une tranche de rythmes.§Le choix T règle le budget de queue via a(T).§T et S sont deux paramètres distincts ; les limites doivent être suivies séparément.
finite_rank§5§Rang fini§A_N=Σₖ≤N u_k⟨v_k,·⟩§Quelques gestes suffisent pour cette machine.§Image de dimension finie ; approxime en norme les compacts sur Hilbert.§La possibilité d’approximer ne fournit pas les coefficients ni leur erreur certifiée.
neumann§5§Série de Neumann§(I−K)^(−1)=Σₙ≥₀K^n si ||K||<1§On corrige le dessin par petits retours de plus en plus faibles.§Inverse borné avec contrôle 1/(1−||K||).§Utilisable pour le bloc de queue seulement après une borne stricte.
local_global§5§Compatibilité locale et globale§Q_arch−Q_pr§Deux règles doivent tenir sur la même balance.§Le signe est porté par leur interaction sur les mêmes tests admissibles.§Deux scores indépendants ne constituent pas cette interaction.
contraction§3§Contraction du support§D_λf(x)=λ^(−1/2)f(x/λ)§On rapproche le dessin du centre avant de lisser.§Pour 0<λ<1, réduit le support ; bornée et continue à λ=1 dans R.§Ne préserve pas les moments ; on les corrige après le lissage.
graph_goal§5§But du graphe§Q_W≥0 sur tous les tests admissibles§La destination est connue, les passages restent à construire.§Via critère de Weil et cœur/continuité, ce signe global est équivalent à RH.§Le chemin inconnu ne rend pas le but indéfini ; réfuter une route ferme une arête, pas la destination.
reproducibility§5§Reproductibilité§protocole + données + code + empreintes§On garde la recette avec le gâteau.§Protocole pré-écrit, scripts, résultats, provenance et SHA-256 conservés.§Reproduire une valeur numérique ne transforme pas son statut en preuve.
hash§1§Empreinte SHA-256§SHA256(fichier)§Une étiquette reconnaît le même paquet.§Résumé cryptographique des octets pour suivre les versions.§Une empreinte contrôle l’identité des octets, pas leur vérité mathématique.
shape§1§Type§objet : X§Une boîte dit quels jouets elle accepte.§Métadonnée domaine, métrique, support, moments et statut pour les traductions.§Le validateur ne vérifie que les informations effectivement représentées.
question_open§5§Question ouverte§obligation sans preuve ni réfutation§Une porte attend encore sa clé.§Statut explicite, hypothèses et témoin de réussite/réfutation déclarés.§Ouvert ne signifie ni impossible ni démontré.
no_go§5§Résultat d’impossibilité§pas de c>0 en H¹§Une clé ne peut pas ouvrir cette serrure précise.§Compactité T_S et dimension infinie excluent la coercivité H¹ stricte.§Cette impossibilité ne ferme pas la positivité ni la métrique R.
time_parameter§1§Paramètre de recherche§n, S, δ, T§Plusieurs boutons portent leurs propres noms.§n dimension, S support, δ lissage, T fréquence ; unités conventionnelles déclarées.§Aucun n’est automatiquement un temps physique.
threshold_schur§5§Seuil du couplage§a≥c*G†c et c∈Ran G§Le nouveau jouet doit payer ses attaches.§Critère exact PSD d’une extension avec G⪰0 ; théorème de Schur.§Tester a≥0 seul ne suffit pas.
method_proof§5§Démonstration§hypothèses ⇒ conclusion§Chaque pas du chemin tient sur une pierre vérifiée.§Argument logique avec domaines et quantificateurs explicites.§Un diagramme ou un calcul concordant illustre la preuve, mais ne la remplace pas.
numeric_evidence§5§Résultat numérique§40/70 chiffres concordants§Deux règles lisent presque la même taille.§Contrôle exploratoire de stabilité à précision accrue ; erreurs comparées.§Pas d’arrondi dirigé ni d’intervalle pour le signe dans V644.
bound_uniform§5§Borne uniforme§∀n, constante C commune§La même règle tient pour toutes les boîtes.§Dépendances autorisées explicites ; pour RH il faut gérer tous les supports aussi.§Une constante fixée après chaque calcul n’est pas une loi globale.
analytic_cont§2§Prolongement analytique§F prolongée depuis un domaine§Le dessin continue quand ses règles le forcent.§Unicité sur domaines connexes par identité analytique ; méromorphe si pôles.§Cela ne donne pas automatiquement l’emplacement des zéros.
tonot§5§Traduction sans perte de signe§inertie conservée§Les pièces changent, la balance répond pareil.§Congruence inversible d’une forme, ou identité des Q sous translation/phase.§Une compression non inversible peut perdre des directions négatives.
sign_change§5§Changement de signe§λ passe par zéro§La balance touche sa marque avant de basculer.§Continuité hermitienne et contrôle de multiplicité nécessaires au suivi.§Une collision de valeurs propres n’est pas une collision de zéros de ζ.
gauge§5§Choix de représentation§base, centre, phase commune§On choisit comment dessiner le même objet.§Certaines transformations conservent relations et signe ; elles sont listées séparément.§Ne pas inclure le changement d’échelle ou modulation variable comme invariances sans preuve.
comparison§5§Comparaison de métriques§H¹↪X_S↪L²§Trois règles regardent le même dessin.§Injections continues ; X_S→L² compacte à support fixé ; H¹ plus fort que R.§L’opérateur de Riesz n’est pas le même dans ces trois règles.
source§1§Provenance§document, section, code, statut§Chaque mot garde son carnet d’origine.§Trace vers définition ou preuve locale, registre hérité et programmes.§Un statut ancien est conservé comme historique, pas comme validation nouvelle.
epsilon0§5§Erreur bilinéaire et noyaux§q continue dans la norme choisie§La balance varie doucement quand le dessin bouge.§Continuité étend Q du cœur lisse au domaine fermé.§Une extension n’augmente pas le nombre de signes prouvés.
area§1§Aire et carré de taille§||cf||²=|c|²||f||²§Doubler les côtés multiplie une aire par quatre.§Homogénéité quadratique ; règle exacte pour normes et formes hermitiennes.§Si Q(f)<0, |c|²Q(f) reste négatif : le carré du coefficient ne change pas ce signe.
realification§4§Parties réelle et imaginaire§f=u+iv, Q(f)=Q(u)+Q(v)§Deux dessins réels portent une flèche complexe.§Pour une forme à coefficients réels symétriques, les termes mixtes s’annulent.§La propriété dépend de la forme réelle ; les phases d’autres paramètres peuvent rester dans ses coefficients.
translation_defect§4§Défaut de translation§||U_xf−f||²=2||f||²−2Re h_f(x)§On compare le dessin à son petit déplacement.§Identité exacte L² ; pour H¹, défaut≤x²||f′||².§Le défaut est positif, mais Q_W soustrait aussi une masse et les premiers.
regularity_scale§3§Régularité progressive§C³, H⁴, H₀³, H¹§On choisit combien de pentes le dessin sait porter.§Échelles distinctes classiques/faibles avec traces ; la graine de V644 est C³ et H₀⁴.§Ne pas confondre classe finie et lissage infini.
moment_matrix§4§Matrice de correction§[[A,−A/2],[A,A/2]]§Deux retouches règlent deux balances.§Pour φ paire et A=∫φe^(x/2)>0, moments de φ,φ′ donnent déterminant A².§L’ordre des lignes ± et les signes doivent rester annoncés.
power_prime§2§Puissance première§n=p^m§Une tour faite d’une seule brique première.§Indices portant Λ(n) ; liste exacte finie à support fixé.§Inclure toutes les puissances, pas seulement les premiers simples.
arctan§2§Arc tangente et artanh§atan z, artanh z§Deux petites règles inversent des courbes.§Pour les queues archimédiennes réelles ici z=e^(−S)∈(0,1), formules usuelles.§Les branches complexes ne sont pas utilisées dans ces quadratures réelles.
energy_arch§4§Énergie de déplacement§E_arch=∫w||U_xf−f||²§Les petits glissements paient une contribution positive.§Forme positive, fermée par multiplicateur Fourier a(τ).§E_arch seule n’est pas Q_W ; soustractions arithmétiques restent présentes.
cross_term§4§Terme croisé§2Re(c̄_i c_j q(f_i,f_j))§Une attache relie deux jouets.§Partie indispensable d’une forme sur une somme.§Sa phase peut rendre négative une somme à diagonales positives.
partition§4§Découpage tête et queue§X_S=V⊕_R V⊥§Une boîte petite et tout ce qui reste.§Décomposition orthogonale R ; blocs de Q et couplages définis.§La tête et la queue sont liées par G₀₁ ; elles ne sont pas deux tests indépendants.
proper_metric§5§Métrique indépendante§R ou B définies sans Q≥0§La règle doit exister avant la décision de la balance.§Norme externe positive démontrée sans hypothèse RH ; permet un Riesz signé.§Définir la norme comme √Q_W avant d’avoir prouvé Q_W≥0 serait circulaire.
conditional§5§Théorème conditionnel§si queue certifiée et Schur≥0, alors signe§Une porte s’ouvre seulement quand ses deux clés existent.§Énoncé démontré avec prémisses encore ouvertes clairement listées.§Ne pas annoncer la conclusion seule comme acquise.
index_all§5§Inventaire technique§AST : fichiers, fonctions, classes§On donne une adresse à chaque petit outil du programme.§Index automatisé des déclarations Python avec ligne et docstring ; export JSON/CSV.§Une fonction Python n’est pas nécessairement un opérateur mathématique.
normalization§4§Normalisation§v*Bv=1§On mesure tous les dessins avec la même règle.§Fixe le quotient et rend comparables les formes dans une métrique donnée.§Les valeurs propres ordinaires de G sans B dépendent du choix de coordonnées.
symbol_relation§5§Du symbole à la relation§Pψ∈kerℓ₊∩kerℓ₋§Un signe devient une attache vérifiable.§La grammaire transporte les relations, pas seulement les noms.§La conservation d’un dessin linguistique ne prouve aucune conservation mathématique.
interest_zone§5§Zone d’intérêt§obligation + gain double + coût + réfutation§La carte montre les portes qui partagent une clé.§Priorités déclarées sur les contrats établis et manquants ; pas de probabilité inventée.§Un score éditorial guide l’essai, jamais la vérité de RH.
program_loop§1§Boucle de programme§for k in indices§On répète une recette pour chaque jouet de la liste.§Instruction finie ou contrôlée du code ; indices et plafond explicites.§Une boucle finie ne vérifie pas le quantificateur ∀n.
result_log§5§Journal avant/après§prévision horodatée ; résultat séparé§La recette est écrite avant de goûter.§Protocoles et résultats distincts, empreintes figées.§Une idée issue d’un résultat est étiquetée comme analyse postérieure.
closure§3§Fermeture§closure V§On ajoute les dessins approchables.§Fermeture dans une topologie déclarée, ici H¹ ou R.§Changer la topologie peut changer la fermeture et les conclusions.
monotone§4§Convergence monotone§f_n↑f ⇒∫f_n↑∫f§On ajoute toujours des briques positives.§Théorème utilisé pour a(τ) et sa divergence avec séries positives.§Les séries signées arithmétiques ne satisfont pas automatiquement ce cadre.
finite_S§5§Support fixé§S fixé avant les estimations§On travaille dans une boîte choisie.§Toutes les preuves compactes et réductions finies valent séparément pour chaque S.§Pour RH, il faut encore une loi couvrant tous les S.
branch_log§2§Branche du logarithme§Log F sur domaine sans zéro§On choisit où la rotation commence.§Un logarithme holomorphe exige domaine approprié et absence de zéro ; sinon branches locales.§La phase globale et les passages de branches ne sont pas résolus par une formule locale.
certificate_sign§5§Signe certifié§λ_min≥borne>0 ou témoin négatif encadré§La petite boîte du résultat reste d’un seul côté.§Exige erreur validée pour forme, métrique, spectre ou témoin.§V644 fournit des diagnostics concordants, pas ces encadrements transcendantes.
play§1§Jeu contrôlé§transformer → comparer → expliquer§On essaie un geste et on regarde quelles attaches tiennent.§Exemples interactifs de contrats autorisés/refusés et invariants associés.§Le jeu illustre la grammaire ; les sorties sont celles de contrats écrits, pas une recherche automatique de preuves.
destination§5§Destination et chemin§RH ↔ positivité globale de Weil§On sait la porte finale ; les clés restent à fabriquer.§But précis et critères équivalents connus ; nouvelles routes nécessitent preuves intermédiaires.§Prouver une route impossible est utile si sa portée exacte est conservée.
scope_dictionary§1§Périmètre du dictionnaire§maths + 95 métaphores + index code§Les mots ont des tiroirs différents.§Noyau explicatif des objets mathématiques, registre nommé complet et déclarations Python inventoriées.§Ne prétend pas avoir désambiguïsé chaque symbole de toutes les archives historiques.
constant_pi§1§Nombre π§π≈3,14159§Le tour d’un cercle comparé à sa largeur.§Constante réelle dans les normalisations Fourier et Gamma.§Une approximation décimale n’est pas une valeur rationnelle exacte.
absolute_conv§3§Convergence absolue§Σ|a_n|<∞§Toutes les briques tiennent même sans leurs signes.§Autorise réarrangement d’une série et facilite les échanges.§Ne pas présumer cette propriété dans la bande critique d’une série de Dirichlet.
singular§4§Matrice singulière§det G=0§Le puzzle a une direction aplatie.§Noyau non trivial ; l’inverse ordinaire n’existe pas.§Un Schur avec G^(−1) est interdit ; pseudo-inverse et range exigés sous PSD.
positive_definite§4§Définie positive§v*Bv>0 pour v≠0§La règle ne confond aucun dessin avec zéro.§Pour la famille indépendante, B_H¹ est exactement définie positive.§Une minuscule valeur numérique ne signifie pas une singularité exacte.
positive_semidefinite§4§Semi-définie positive§v*Gv≥0§La balance permet des directions à zéro.§Peut avoir un noyau ; ordre hermitien.§Dans Schur, les nouveaux couplages doivent être compatibles avec ce noyau.
integration_parts§3§Intégration par parties§∫ψ″e^(±x/2)=¼∫ψe^(±x/2)§On déplace la pente d’un dessin vers l’autre.§Identité sous traces ψ=ψ′=0, explique ℓ±Pψ=0.§Sans conditions de bord, des termes supplémentaires restent.
parity_flag§5§Drapeau par secteurs§V_pair⊕V_impair§On range d’abord selon les deux miroirs.§Schur peut être calculé par bloc de parité ; pivot interprété dans son drapeau.§Comparer à un ordre mélangé nécessite garder la même extension ou signaler un nouveau drapeau.
proof_open§5§Portée des nouveaux lemmes§L1–L7 auxiliaires§Les ponts construits portent leurs panneaux.§Admissibilité, densité, métriques, compactité et réduction conditionnelle ; pas signe global.§La nouveauté bibliographique de ces constructions n’est pas revendiquée.
admisscomplex§3§Tests complexes admissibles§f=u+iv, ℓ±u=ℓ±v=0§Deux dessins passent chacun les deux portes.§Domaines se complexifient ; forme complète hermitienne.§L’arbitraire complexe d’un coefficient de cette famille n’épuise pas toutes les familles antérieures.
periodicity§2§Périodicité§f(x+T)=f(x)§Le dessin recommence après le même pas.§Relation exacte à période déclarée ; utilisée dans des mécanismes de rigidité.§Le support compact, une fonction entière et un caractère modulo q ont des domaines différents.
realpart§1§Partie réelle§Re z=(z+z̄)/2§On garde le pas droit de la flèche.§Projection ℂ→ℝ ; intervient dans Q_pr et polarisation.§Oublie la composante imaginaire ; ne permet pas de reconstruire la phase seule.
transpose§4§Transposée conjuguée§C*=conj Cᵀ§On échange lignes et colonnes avec leur miroir.§Adjoint matriciel pour métrique euclidienne ; congruence utilise C*GC.§Pour métrique B, l’adjoint opérateur est B^(−1)C*B si inverses valides.
comparison_bound§5§Borne versus égalité§≤ ou =§Une règle sait si elle compte exactement ou encadre.§Égalité structurelle, inégalité estimative, valeur numérique et image ont des statuts séparés.§Ne pas remplacer un signe ≤ par = pour embellir une analogie.
acceptance§5§Règle d’arrêt§réussite, réfutation, indéterminé§Le jeu sait quand ranger son résultat.§Chaque essai déclare les trois issues ; absence de preuve reste indéterminée.§Un timeout ou un plafond atteint ne prouve pas une impossibilité.
cost§5§Coût d’un passage§norme, erreurs, calcul§La traduction paie ses changements.§Coût mathématique par bornes et coût de calcul par expérience ; choix éditorial distinct.§Un coût faible ne prouve pas le signe ; il rend une route testable.
lowfreq§5§Noyau de basse fréquence§sin(T(x−y))/(π(x−y))§Les rythmes lents se recouvrent dans la boîte.§Noyau de 1_[−S,S]Π_T1_[−S,S], compact positif à support fixé.§Borne de queue effective à construire avec approximation contrôlée du noyau et contraintes.
weilsign§5§Critère de Weil§RH ↔ Q_W≥0 sur le cœur admissible§La même destination se lit dans une autre langue.§Équivalence utilisée avec normalisation complète, moments et continuité ; références CC21/doc67.§La réduction I−compact établit la structure, pas cette inégalité.
hamilton§5§Analogie Hamilton–Jacobi–Bellman§décomposition optimale ≠ preuve RH§On cherche une route qui paie toutes ses attaches.§Bellman aide au choix de contrats ; Schur minimise exactement une forme si le bloc est positif.§Une équation de décision ne crée pas la structure positive manquante.
invariant_list§5§Famille d’invariants§moments, corrélation, inertie, dette§Les attaches survivent à des gestes différents.§Chaque invariant a son groupe de transformations et ses gardes propres.§Aucun invariant unique conservé par tous les gestes n’est revendiqué.
codimension§4§Codimension§codim E_S=2§Deux balances retirent deux libertés.§Deux moments indépendants continus coupent un sous-espace fermé.§Codimension finie n’implique pas dimension finie du domaine.
dual§4§Dualité§ℓ(f)§Un petit capteur lit un dessin.§Fonctionnelle linéaire continue sur l’espace choisi ; normes et adjoints associés.§Un capteur qui ne lit rien peut laisser des modes invisibles.
distribution§3§Distribution§δ_a et Df au sens faible§Un dessin peut être reconnu par son effet sur les tests.§Forme linéaire continue sur Cc∞ ; dérivées définies par dualité.§Une masse de bord change l’équation Pψ=f ; il faut annuler les traces.
prototype§5§Prototype versus theorem§code de grammaire + lemme rédigé§Un petit jouet explique une grande machine.§Le prototype inspecte les contrats représentés ; le théorème est dans le dossier de preuves.§Ne pas confondre exécution du validateur et preuve automatisée des lemmes.
classification§5§Statut épistémique§définition / prouvé / numérique / ouvert§Chaque mot porte sa couleur de vérité.§Statut par assertion, source et portée ; les métaphores gardent leur statut hérité.§Le statut d’un nom n’est pas un certificat de toutes ses utilisations.
research_state§5§État final recherché§loi arithmétique de tous les Schur§Toutes les portes finales partagent une règle.§Soit démontrer G_eff,S⪰0 pour tous S ; soit témoin négatif certifié réfutant le signe/RH sous critère complet.§Un résultat positif fini seul ne termine pas la recherche.
no_destination§5§Limite d’une carte§arêtes manquantes explicites§Une carte montre aussi les ponts absents.§Le graphe distingue constructions acquises, hypothèses et obligations.§Une carte complète des idées n’est pas une carte de toutes les preuves possibles.
continuous§3§Continuité d’une forme§|q(f,g)|≤C||f||||g||§De petits changements du dessin font de petits changements de la balance.§Permet extension par densité au domaine annoncé ; C peut dépendre de S.§Ce contrôle n’est pas une minoration positive.
orthogonal§4§Orthogonalité§⟨f,g⟩=0§Deux dessins ne s’attachent pas dans cette règle.§Relation métrique ; V⊥_R diffère en général de V⊥_H¹.§Découplage dans la métrique ne supprime pas les couplages de Q_W.
dependent§4§Indépendance linéaire§Σc_kf_k=0 ⇒ c_k=0§Aucune pièce ne se refait avec les autres.§Garantie par indépendance des graines et injectivité P pour la famille.§La matrice de Gram numérique mal conditionnée peut masquer cette indépendance exacte.
posthoc§5§Analyse après résultat§nouvelle question issue d’un calcul§On écrit ce que le jeu nous a appris ensuite.§Documentée comme postérieure ; une nouvelle expérience doit avoir son nouveau protocole.§Ne jamais rebaptiser ce choix comme prévision antérieure.
linear§1§Linéarité§A(af+bg)=aAf+bAg§La machine respecte l’assemblage des dessins.§Propriété des opérateurs P, translations, transforms et corrections fixes.§Q est quadratique, pas linéaire ; il contient des attaches croisées.
quadratic§1§Forme quadratique§Q(cf)=|c|²Q(f)§La pile grandit au carré de la taille.§Forme issue d’un couplage hermitien ; domaine annoncé.§Homogénéité quadratique seule n’implique pas Q≥0.
support_diameter§3§Diamètre du support§D=b−a§On mesure la largeur de la valise.§Pour supp f⊂[a,b], h_f(t)=0 si |t|>D.§Le centre ne change pas le plafond e^D ; une fenêtre plus large peut le surestimer.
duality_mellin§5§Moments vus en Mellin§Mℒf(0)=ℓ₋f, Mℒf(1)=ℓ₊f§Les deux balances deviennent deux notes sur une autre portée.§Identités exactes du passage additif/multiplicatif.§Garder seulement ces deux notes oublie le reste du spectre.
compact_sequence§5§Test de compactité§e_n orthonormale ⇒||T_Se_n||→0§Des dessins de plus en plus différents deviennent petits après la machine.§Pour T_S compact et e_n faible→0 ; entraîne Q_W(e_n)→0.§Ne dit pas de quel côté de zéro les valeurs arrivent.
tail_precision§5§Précision versus extension§40/70 digits ; n≤8§On affine la règle puis on agrandit la boîte.§Deux expériences différentes : stabilité de calcul et couverture de sous-espace.§Plus de chiffres et plus d’indices ne sont pas des garanties de tous les tests.
schur_numerical§5§Dette numérique§δ calculée à 40/70 digits§La balance annonce une lecture qu’on recoupe.§Diagnostic avec inverses multiprécision et même drapeau.§Près d’un pivot nul, une certification séparée devient essentielle.
domain_guard§5§Garde de domaine§entrée admissible, métrique correcte§La machine vérifie la boîte du jouet.§Conditions nécessaires représentées dans le validateur.§Une garde passée ne prouve pas d’hypothèses absentes du modèle.
global_certificate§5§Certificat de famille§taux de queue + Schur + ∀S§La recette ferme toutes les dernières portes.§Objectif du prochain protocole : borne calculable et loi de signe complète.§Encore ouvert ; la réduction structurelle ne l’a pas fourni.
reading§1§Lecture progressive§image → formule → contrat → preuve§On apprend les mots puis les phrases.§Quatre étapes d’apprentissage, chacune consultable séparément dans le dictionnaire.§L’explication enfantine aide la compréhension et garde sa limite précise.
grammar_route§5§Phrase mathématique§graine→test→forme→paire→Schur§Les mots forment un trajet autorisé.§Chaque arête garde son domaine, ses relations, son statut et son coût.§La dernière flèche vers RH reste conditionnelle au signe de toute la famille.
branch_obligation§5§Obligation de branches§continuer sans perte d’identification§Il faut nommer le chemin avant et après le croisement.§Question antérieure ouverte du corpus ; la nouvelle voie de formes évite de suivre chaque zéro pour le critère.§Elle ne résout pas les passages de branches comme problème indépendant.
positive_temperature§2§Chaleur et positivité§Q_chaleur peut avoir un signe§Une pile reçue ou donnée n’a pas la même flèche.§La chaleur échangée a un signe selon convention ; température absolue et énergie cinétique sont d’autres notions.§Aucune analogie thermique n’autorise la positivité de Q_W.
map_closed§5§Route fermée§c_H¹>0 impossible§On barre une arête qui ne peut pas tenir.§Résultat précis du no-go compact ; conserve le signe ouvert et le pont R.§Une impasse locale n’est pas l’échec de l’objectif global.
bound_cross§5§Coût des couplages§||G₀₁G₁₁^(−1)G₁₀||§Les attaches de l’infini reviennent tirer sur la tête.§Terme positif soustrait si queue positive ; borne via marge et norme de couplage.§Omettre ce terme serait une réduction incorrecte.
lemma§1§Lemme§petite proposition démontrée§Une pierre solide aide à construire un pont.§Résultat utilisé pour une étape plus large ; hypothèses et preuve écrites.§Petit n’est pas faible : un lemme de traduction peut fermer plusieurs obligations.
theorem§1§Théorème§énoncé + hypothèses + preuve§Un pont complet dit ce qu’il porte.§Résultat logique de portée explicitée ; conditionnel si hypothèses non acquises.§Une preuve auxiliaire peut être complète sans être une preuve de RH.
metaphor§1§Métaphore§image accompagnée d’une garde§Un dessin aide à retenir un mot.§Registre de 95 noms avec ancrage et endroit où l’image casse.§Un opérateur ne naît pas de son nom : définition et domaine sont indispensables.
dictionary_id§1§Identifiant stable§math:p_operator, metaphor:…§Chaque boîte a une adresse unique.§Noms techniques désambiguïsés même quand une lettre est partagée.§Les alias servent à chercher ; seuls les identifiants qualifiés composent les contrats.
fixed_S_spectrum§5§Exceptions spectrales finies§λ(I−K_S)<0 en nombre fini§Quelques dessins peuvent encore pencher vers le bas.§K_S compact ; valeurs κ>1 en nombre fini, multiplicités incluses.§Leur signe doit encore être décidé pour chaque support.
reduction_analytic§5§Réduction analytique établie§Q_W=R−B_S§La même balance se lit avec une règle adaptée.§B_S continu L² et j_S compact ⇒ I−j_S*B_Sj_S.§La notation B_S de cette forme L² doit être distinguée de la matrice B_H¹.
kernel_series§4§Série du noyau§w(x)=Σₙ≥₀e^(−β_nx)§Le poids est une pile de petites décroissances.§Série positive pour x>0 ; Tonelli produit la série de a(τ).§Le calcul spectral emploie des termes positifs du noyau, pas des zéros de ζ.
conclusion_guard§5§Garde de conclusion§fini → sous-espace ; ∀ → global§La porte finale sait quelles clés manquent.§Le validateur refuse une promotion finie→globale sans contrat de queue et couverture.§Cela représente une règle du protocole, pas un décideur universel de théorèmes.
expansion§2§Développement de Taylor§e^x=Σx^k/k!§Les petites briques reconstruisent la courbe.§Série entière et contrôles rationnels de reste pour x rationnel≥0.§Les coefficients exacts ne rendent pas automatiquement exacte une quadrature.
arithmetic_bridge§5§Pont arithmétique restant§signe de Schur pour tous S§La dernière clé doit parler la langue des premiers.§Contrat global impliquant primes, masse et archimédien ensemble.§Ouvert ; pas résolu par compactité ou une jolie grammaire.
legend§1§Légende du graphe§plein=acquis ; pointillé=obligation§La carte explique la solidité de ses chemins.§Code de lecture des preuves, expériences et tâches à venir.§La couleur ne constitue pas un statut scientifique sans sa source.
typed_error§5§Erreur typée§ε_H¹, ε_R, ε_L²§Chaque manque porte la règle qui l’a mesuré.§La même erreur dans des normes différentes n’est pas interchangeable.§Toute conversion d’erreur exige une borne de transport.
signed_operator§4§Opérateur signé§T=T*, sans T≥0 acquis§La machine peut tirer vers le haut ou le bas.§Riesz de la forme complète sans présupposer RH.§Le qualifier de positif avant preuve serait circulaire.
hermitian_extension§4§Extension de forme§[[G,c],[c*,a]]§Le nouveau jouet arrive avec toutes ses attaches.§Bloc hermitien ; seuil Schur exact lorsque hypothèses satisfaites.§Ajouter la seule diagonale a perd l’information relationnelle.
side_prime_arch§5§Deux côtés d’une identité§Q_arch = Q_W+Q_pr§On compte les mêmes piles de deux façons.§Normalisation vérifiée par deux expressions archimédiennes dans les calculs V644.§Concordance numérique n’est pas une nouvelle preuve indépendante du signe.
internal_result§5§Résultat interne§preuve rédigée et auditée§Le pont a été relu dans les deux sens.§Portée locale démontrée dans le dossier ; aucune priorité bibliographique revendiquée.§La relecture critique augmente la fiabilité mais n’est pas une validation éditoriale externe.
time_support§5§Support versus horizon Bellman§S≠horizon de décision§Deux boîtes ne mesurent pas la même durée.§S paramètre analytique, horizon nombre d’actions de recherche.§Leur ressemblance linguistique ne fournit pas de pont mathématique.
unknown§1§Indéterminé§ni preuve ni réfutation§On laisse une case vide quand la règle ne tranche pas.§Issue normale d’une expérience ou d’une obligation non résolue.§Une case vide ne doit pas être remplie par une confiance chiffrée inventée.
comparison_forms§4§Même forme, autre opérateur§T_H¹ et I−K_R§Le dessin reste ; la règle et la machine changent.§Q_W identique sur intersection des domaines, représentations Riesz distinctes.§Ne pas appeler ce changement une conjugaison unitaire sans isométrie démontrée.
closure_core§5§Cœur de la métrique R§contraction→lissage→correction moments§On rentre le dessin, le polit et règle les deux balances.§Approximation forte dans R, support intérieur et moments exacts ; preuve V644.§Il faut les trois gestes, car contraction et convolution peuvent déplacer les moments.
tail_constant§5§Constante η de queue§||j_S|V⊥||≤η§La partie oubliée est petite dans la règle L².§Mesure l’injection sur complément R ; η→0 le long d’une exhaustion dense orthogonale.§Le taux effectif pour notre famille demeure à calculer/certifier.
all_S§5§Couverture des supports§S=1,2,3,… suffit avec inclusion§On agrandit les boîtes jusqu’à couvrir chaque dessin.§Chaque test compact entre dans une fenêtre entière ; encore tous les indices/tests dans cette fenêtre.§Trois ou quatre fenêtres ne remplacent pas l’ensemble des entiers.
bellman_reward§5§Récompense de contrat§gain=obligations réellement fermées§On compte les clés vérifiées.§Valeur de planification liée aux preuves ou réfutations ; double gain quand une construction ferme deux obligations.§Un gain éditorial n’est pas une unité d’énergie ni un taux de vérité.
dictionary_scope§5§Archives et symboles non typés§inventaire explicite, pas universel§Les tiroirs connus sont nommés ; les autres sont signalés.§Cette édition couvre le noyau expliqué, tous noms du registre et toutes déclarations Python analysables.§Les objets propres à chaque archive peuvent demander une fiche future ; ne pas inventer leur définition.
what_open§5§Ce qui demeure ouvert§signe global, branches, collisions, A§Les portes manquantes restent sur la carte.§La voie de formes fournit une autre approche du signe ; problèmes de suivi indépendants non résolus.§Le diagnostic positif de nos petites matrices ne ferme aucune de ces obligations.
novelty§5§Originalité versus utilité§construction utilisable ≠ priorité§Une clé utile peut avoir été fabriquée ailleurs.§Les résultats internes sont présentés comme ponts reconstruits ; revue de nouveauté à faire si article soumis.§Ne pas annoncer un nouveau théorème dans la littérature sans recherche bibliographique complète.
operator_dictionary§1§Dictionnaire progressif§1→5§On apprend les petits mots avant les grandes phrases.§Niveaux alphabets, fonctions, domaines, formes et contrats ; chaque fiche possède une garde.§Les niveaux sont pédagogiques, pas un classement de difficulté des preuves.
finite_psd§5§Diagnostic PSD fini§G_W(S,n) calculée positive§Les dessins de la petite boîte tiennent la balance.§Observation numérique limitée aux paramètres testés et précision déclarée.§PSD n’est pas certifiée par ce mot tant que l’erreur transcendante n’est pas encadrée.
translation_contract§5§Contrat de traduction§entrée, sortie, relations, coût, statut§La machine garde son ticket de passage.§Structure de chaque règle de la grammaire V644 ; testable par le prototype.§Un contrat descriptif doit renvoyer à un argument mathématique pour être qualifié de démontré.
fictitious_mass§1§Masse et vitesse fictives§unité M, unité V, MV²§Des étiquettes suivent les multiplications.§On peut poser des unités formelles, mais cela ne construit pas une factorisation positive de Q_W.§Chercher Q=MV² avec M≥0 est une nouvelle assertion à prouver, pas une conséquence des étiquettes.
laplace_like§3§Transformée exponentielle§F(s)=∫f(x)e^((s−1/2)x)dx§On écoute le dessin avec une autre intensité.§Fonction entière pour support compact ; Fourier sur s=1/2+iτ à normalisation près.§Appeler cette transformée Mellin exige le passage ℒ et sa mesure.
global_energy§5§Factorisation positive recherchée§Q_W(f)=||Af||² éventuellement§La balance serait une aire de dessin.§Une telle représentation avec domaine et métrique indépendante prouverait la positivité.§Aucune factorisation globale n’est acquise ; elle ne doit pas être postulée.
spectral_measure§5§Mesure spectrale§Q(f)=∫λ dμ_f(λ)§La balance répartit ses poids par rythme.§Pour opérateur autoadjoint borné dans la métrique fixée, théorème spectral.§Une mesure positive μ_f n’impose pas λ≥0 sur son support.
common_support§3§Support commun d’une famille§supp f_i⊂[−S,S]§Tous les dessins jouent dans la même boîte.§Garantit mêmes plafonds et constantes arithmétiques pour la compression.§Union de supports éloignés peut augmenter le diamètre des combinaisons.
matrix_error§5§Erreur matricielle§||ΔG||, ||ΔB||§La table aussi a une petite boîte d’erreur.§Contrôle spectral après normalisation et conditionnement ; intervalles ou bornes.§Comparer seulement les diagonales ne borne pas le spectre.
range_certificate§5§Compatibilité de noyau§c⊥ker G§L’attache ne tire pas dans une direction invisible.§Équivalent à c∈Ran G en dimension finie hermitienne ; nécessaire au Schur PSD singulier.§Une tolérance numérique ne décide pas l’égalité exacte sans preuve/encadrement.
finite_minimum§5§Minimum de Schur§inf_z Q(z+v)=δ§On règle les anciens jouets pour soulager le nouveau.§Valable si ancien bloc >0 ; formule minimisation avec z=−G^(−1)c.§Si le bloc est indéfini, ce minimum vaut −∞ même si la formule algébrique existe.
conditional_global§5§Passage au signe global§queue positive + Schur fini ≥0 + tous S§La dernière phrase exige toutes ses attaches.§Théorème conditionnel complet ; le dossier écrit la réduction et ses obligations restantes.§Le prototype ne dispose pas encore des prémisses globales.
correlation_poly§4§Polynôme de corrélation§h_ij(Sz)=polynôme rationnel, 0≤z≤2§Deux dessins polynomiaux se recouvrent exactement.§Intégrale symbolique sur [z−1,1], calcul par fractions rationnelles.§Ce polynôme vaut sur l’intervalle indiqué ; hors recouvrement la corrélation est zéro.
endpoint_jet§3§Jet au bord§ψ^(j)(±S)=0, j≤3§Les attaches du bord disparaissent jusqu’à quatre niveaux.§Annulation d’ordre 4 de w_S ; assure prolongement C³ et dérivées faibles L² d’ordre 4.§La dérivée d’ordre 4 peut sauter ; ne pas annoncer C⁴ ou C∞.
exact_metric§4§Identité de métrique du moule§||Pψ||H¹²=||ψ‴||²+3/2||ψ″||²+9/16||ψ′||²+1/16||ψ||²§Le moule donne aussi une règle exacte.§Intégration par parties dans H₀³ ; constantes d’équivalence indépendantes de S.§Cette identité concerne la métrique B, pas Q_W.
core_p_dense§5§Densité polynomiale via P§w_S p_n→ψ dans H³§Les petites briques refont tout dessin autorisé.§Pour ψ intérieur lisse, ψ/w_S lisse ; approximation C³ puis P ; extension par cœur.§La densité est démontrée sans les valeurs propres numériques.
compact_no_gap§5§Preuve sans chiffres du no-go§T_S compact, dim E_S=∞§La règle forte rend certaines images minuscules.§Suite orthonormale donne Q(e_n)→0 ; interdit Q≥c||·||H¹².§Aucune direction négative n’en découle.
proof_translation§5§Preuve de translation§h_(U_af)(t)=h_f(t)§La valise déplacée garde ses attaches.§Changement de variable y↦y−a ; ℓ±U_af=e^(±a/2)ℓ±f.§L’adresse du support change même si l’invariant demeure.
complex_phase_proof§5§Preuve de phase§h_(e^(iθ)f)=h_f§Deux rotations identiques se compensent.§Facteurs e^(iθ) et conj e^(iθ) s’annulent dans corrélation et normes.§La compensation n’a pas lieu pour une phase variable aux deux positions.
unit_scale§1§Échelle d’amplitude§f↦cf, [c]=1§On agrandit toutes les pièces pareil.§Q,B,R multipliées par |c|² ; rapports inchangés si c≠0.§c=0 efface le test et n’est pas un changement de base inversible.
math_image§1§Image et idéogramme§moule ; valise ; puzzle ; balance§Quelques dessins rappellent les gestes.§Vocabulaire pédagogique relié à P,U,C et Schur ; les symboles usuels restent canoniques.§Aucune prétendue traduction du chinois n’est nécessaire à la preuve.
approx_window§5§Fenêtre et approximation§S, N, T, δ§Quatre boutons organisent le jeu.§Support, dimension, fréquence et lissage ; ordre des limites doit être décrit.§Laisser tous les boutons tendre ensemble sans contrôle peut perdre le domaine ou le signe.
proper_target§5§Destination précise§Q_W(f)≥0 pour tout f admissible§La carte a une porte finale nommée.§Critère équivalent à RH ; notre nouveau contrat est une réduction du travail restant.§Il reste inconnu si le contrat arithmétique peut être fermé par cette famille et méthode.
current_version§1§Version et mémoire§V6.44 après V6.43§Chaque dessin garde sa date.§Anciens résultats et limites conservés, nouveaux ponts ajoutés dans documents 68 et 69.§Une mise à jour ne transforme pas les anciens diagnostics en preuves.
proof_vs_action§5§Calcul versus contrat§action exécutée ; propriété ouverte§Faire un geste ne dit pas qu’il réussit.§Les matrices sont calculées ; leurs erreurs transcendantes et quantificateurs globaux restent distincts.§Une action terminée peut produire un résultat indéterminé ou fermer seulement une obligation locale.
full_form§5§Forme complète obligatoire§archimédien−premiers§La balance garde tous ses plateaux.§Normalisation de V643 ; aucun calcul de zéros pour construire les matrices V644.§Une forme tronquée autrement exige une nouvelle preuve de relation au critère.
nonphysical§1§Analogie physique§E_ar, R, U_decision§Les étiquettes aident les calculs, chacune dans sa boîte.§Unités fictives suivies ; domaine arithmétique et paramètre de recherche déclarés.§Ne pas identifier Q_W à une énergie cinétique, R à une chaleur ou Bellman à une loi thermodynamique.
final_route§5§Pont restant après réduction§M_Sη²<1 et G_eff,S≥0§Deux dernières clés vont ensemble.§Coups doubles attendus : taux effectif de queue + marge des couplages ; signe arithmétique pour toute la famille.§C’est la prochaine enquête, pas un résultat annoncé.
children§1§Première lecture§image en une phrase§On comprend le geste avant de connaître le nom.§Chaque entrée du noyau possède une explication enfantine puis un ancrage précis.§Les fiches historiques gardent aussi l’image originale, parfois plus technique.
signed_entropy§2§Attention aux signes empruntés§E>0 n’implique pas E′>0§Une pile peut rester grande tout en diminuant.§Contre-exemple simple e^(−t), règle générale de dérivation.§La positivité physique invoquée sans convention ne remplace pas une preuve de forme.
relation_moments§5§Relation admissible conservée§ℓ±f=0§Deux attaches restent fermées.§P, translation et phase commune conservent/provoquent cette relation selon leurs domaines.§Modulation ou changement d’échelle ne la conserve pas en général.
relation_pencil§5§Relation spectrale conservée§Gv=λBv ⇒ G′v′=λB′v′§Le même puzzle se lit avec d’autres noms.§Sous C inversible, v′=C^(−1)v, G′=C*GC, B′=C*BC.§Changer seulement G fait perdre cette relation.
relation_flag§5§Relation de drapeau conservée§V_ancien⊂V_ancien+span(v)§Les anciennes pièces restent dans la boîte.§v→αv+w préserve extension de dimension 1 et normalise les deux Schur identiquement.§Une permutation modifiant V_ancien change le contrat.
interest_priorities§5§Priorité sans probabilité§gain vérifié / obligation manquante§On essaie les clés qui touchent plusieurs portes.§Zones classées par gains conceptuels et possibilité de réfutation ; pas d’espérance inventée.§Le rôle de Bellman est de structurer les alternatives, pas de deviner la vérité.
tail_decision§5§Décision de queue§certifié / réfuté / indéterminé§La boîte oubliée reçoit une vraie étiquette.§Borne η validée et M_S exact/encadré, ou violation ; sinon ouvert.§L’existence compact ne suffit pas à écrire « certifié ».
weill_spelling§1§Weil et noms des sources§André Weil§Le carnet garde le nom correct.§Les demandes « Weill » sont interprétées ici comme Weil, avec sources Wei48 et critère de Weil.§Courbes sur corps finis et critère pour ζ des entiers sont deux contextes distincts.
euler_tower§5§Tour eulérienne locale§coefficients sur p^k§Une même brique monte en étages.§Identités locales du produit d’Euler ; PRIME-LOCK explore leurs défauts.§La tour locale ne donne pas la compatibilité globale positive.
ledger§1§Tenue des unités§[Pψ]=A ; [G]=[B]=A²§Toutes les boîtes gardent leur étiquette.§x sans dimension implique [ψ]=[f]=A pour P ; coefficients de famille sans dimension.§Si on change la dimension de x, P doit recevoir une échelle inverse pour soustraire D² et 1/4.
jet_cert§5§Jets certifiés antérieurs§certificats V635–V642§Les pentes sont encadrées dans des petites boîtes.§Résultats locaux exacts/encadrés dans les fichiers historiques conservés ; consulter leurs domaines.§Ils ne donnent pas une continuité globale de branches ni le signe de toute la forme.
not_all_code§1§Code et mathématiques§outil technique ≠ objet mathématique§Le tiroir des tournevis est à côté des dessins.§L’index technique décrit chaque fonction Python repérée ; le noyau explique les objets.§Ne pas compter les fonctions de génération HTML comme opérateurs de RH.
open_law§5§Loi arithmétique recherchée§tous supports et couplages§Une règle unique doit tenir sur toutes les boîtes.§Borne et identité liant explicitement archimédien, poids premiers et Schur.§Aucune loi de ce type n’est obtenue en V644.
audit§5§Lecture constructive et critique§preuve proposée ↔ objections§On traverse le pont dans les deux sens.§Deux relectures ont vérifié domaines, compactité, parité et quantificateurs.§C’est une vérification interne ; les limites sont conservées dans le rapport.
conditionality§5§Portée du mot équivalent§A⇔B avec mêmes hypothèses§Les deux portes donnent sur le même endroit.§Équivalence logique exige domaines, normalisation et quantificateurs identiques.§Une ressemblance d’unités, d’images ou de symboles n’est pas une équivalence.
question_destination§5§Chemin versus destination§route inconnue ; critère précis§Le but se voit, les ponts manquent.§On peut connaître une formulation exacte du but sans connaître de stratégie qui le prouve.§Réfuter un contrat intermédiaire affine la carte et ne réfute pas nécessairement le but.
data_family§5§Famille expérimentale exécutée§S∈{1/2,1,2,3}, n∈{2,4,6,8}§On joue dans quatre boîtes de quatre tailles.§Matrices arithmétiques complètes à 40 et 70 décimales ; protocole horodaté avant calcul.§Seulement 16 sous-espaces testés, erreur non certifiée ; tous les autres restent hors expérience.
proof_count§5§Lemmes et essais séparés§preuves symboliques ; contrôles de code§Les pierres et les lectures ont deux carnets.§Les identités exactes sont démontrées ; les calculs testent implémentation et stabilité.§Le nombre de tests réussis ne mesure pas la part de RH démontrée.
translation_loss§5§Perte de traduction§ce que T oublie§On écrit les pièces tombées de la valise.§Compression oublie complément ; module oublie phase ; L² oublie dérivée ; suivi local oublie branches.§Un pont utile mesure cette perte au lieu de la nier.
global_arrow§5§Flèche globale conditionnelle§L7 + signe arithmétique ∀S ⇒ RH§La dernière flèche reste pointillée.§La réduction fournit un contrat plus précis ; prémisses manquantes affichées.§Aucune flèche pleine vers RH n’est ajoutée au graphe V644.
certification_future§5§Protocole de certification prévu§intervalle arch + queue + Schur§La prochaine partie ferme les boîtes d’erreur.§Étapes préparées dans le dossier : résidus, inverse de queue, signe effectif et couverture.§Une tâche prévue n’est pas une action déjà accomplie.
arithmetic_invariant§5§Invariant arithmétique encore recherché§loi de dette couvrante§Une attache devrait relier les boîtes de toutes tailles.§Le quotient Schur est invariant de représentation, pas une minoration arithmétique obtenue.§Il ne décide pas du signe tant qu’aucune loi sur ses valeurs n’est démontrée.
math_operator§1§Opérateur mathématique§A:Dom A→Y§Une machine a une porte d’entrée précise.§Application, souvent linéaire, avec domaine, codomaine, norme et paramètres.§Deux machines de même nom peuvent avoir des domaines différents.
prime_cutoff_scope§4§Liste arithmétique finie§p^m≤e^(2S)§La boîte laisse entrer certaines tours seulement.§Support de corrélation dans [−2S,2S] donne finitude exacte.§Cette finitude à S fixé ne rend pas finie la famille des supports.
thin_tail§5§Une queue existe§η_N→0§Les pièces oubliées deviennent petites après la règle douce.§Compactité j_S et exhaustion R-orthogonale dense donnent convergence en norme.§La vitesse et les indices de réussite doivent encore être calculés.
search_bellman§5§Bellman conceptuel§actions sur contrats plutôt que plafond seul§On choisit des ponts qui partagent des clés.§Planification avec dépendances ET/OU et résultats conditionnels ; couplages scientifiques au centre.§Aucune récompense de score n’est promue en preuve.
exact_vs_num§1§Exact et numérique§fraction rationnelle ; décimale§Une règle ferme sa boîte, l’autre donne une lecture.§Algèbre rationnelle exacte pour B et corrélations ; mp pour transcendants.§Les deux colonnes ont des statuts différents même si les chiffres concordent.
domain_ambient§3§Espace ambiant§ℝ, intervalle, demi-droite, ℝ₊§Le dessin dit dans quelle pièce il joue.§Les transforms de V643 relient des espaces précis ; pas des noms seuls.§Une extension par zéro n’est pas une translation et une restriction peut perdre l’isométrie.
end_goal§5§Résultat global encore absent§Q_W≥0 sur X_S pour tous S§Toutes les balances du monde devraient tenir.§Le cœur dense permet cette reformulation, nouvelle structure I−compact établie.§Ni les lemmes ni les résultats numériques V644 ne la prouvent.
learning§1§Apprendre une langue mathématique§mot → relation → opérateur§Les mots nouveaux servent à faire des gestes.§La langue inventée renomme des gestes canoniques et rend les compositions visibles.§Elle guide les essais ; elle ne remplace pas les définitions usuelles.
conditioned§4§Conditionnement§κ(B)=λ_max(B)/λ_min(B)§Une règle presque écrasée rend les lectures fragiles.§Mesure spectrale pour B>0 euclidien ; amplifie les erreurs de normalisation.§Diffère des autres κ du corpus ; sa valeur est propre à la base.
index_domain§5§Fonction technique indexée§fichier:ligne, signature, docstring§Chaque tournevis trouve son tiroir.§Index AST complet des déclarations analysables du corpus courant, export UTF-8.§Sans docstring explicative, le dictionnaire n’invente pas le comportement.
archive_status§5§Statut hérité d’une métaphore§statut dans registre V6§L’ancien carnet garde son encre.§Le libellé est repris avec section et ligne, sans validation scientifique nouvelle.§Une absence de statut explicite est signalée ; pas comblée arbitrairement.
core_contract§5§Contrat du cœur§approximation forte + moments + support§Les dessins lisses approchent sans sortir de la boîte.§Le domaine R et le signe se relient au critère via densité prouvée.§La seule densité L² n’aurait pas suffi.
head_test§5§Tête effective§Q₀₀−Q₀₁Q₁₁^(−1)Q₁₀§La petite boîte reçoit la vraie traction de l’infini.§Forme finie exacte après queue coercive ; représentable dans toute base de V.§Sa matrice exige contrôle de résolvante/couplages, pas seulement la compression Q₀₀.
method_scope§5§Recherche poursuivie§construction, expérience, contrat ouvert§Le jeu avance en laissant les cases honnêtes.§V644 ferme des obligations auxiliaires et prépare la prochaine loi arithmétique.§Ne prétend pas avoir publié ni validé une preuve de RH.
warmup§1§Commencer par une balance simple§G=[[1,2],[2,1]]§Deux jouets montent seuls mais tirent ensemble vers le bas.§Diagonales positives, vecteur (1,−1) donne −2 ; montre le rôle du terme croisé.§Exemple pédagogique synthétique, pas matrice de la fonction zêta.
toy_invariant§1§Jeu de changement de noms§C inversible§Le puzzle change de noms, pas de réponse.§Application de la congruence simultanée ; invariants exacts expliqués.§Une transformation non inversible peut supprimer une pièce critique.
frozen§5§Protocole figé§SHA du protocole avant données§La recette garde son premier ticket.§Supports, dimensions, précisions et critères de stabilité fixés avant calcul.§De nouvelles questions après calcul seront marquées comme telles.
reflection§3§Réflexion§Rf(x)=f(−x)§Le dessin passe devant le miroir.§Unitaire sur métriques ; Q invariant car corrélation symétrique.§Ce R de réflexion est distinct de la métrique R(f).
reflection_metric§5§R notation qualifiée§R_metric, R_reflection§Deux boîtes séparent une lettre partagée.§La métrique logarithmique et l’opérateur miroir ont des rôles différents.§L’identifiant stable empêche une composition ambiguë.
full_definitions§1§Lire une fiche§image, formule, domaine, garde§Le mot raconte son geste puis montre ses règles.§Toutes les fiches du noyau ont ces champs ; statut précis renvoie à preuve/source.§Une fiche pédagogique ne doit pas être citée comme unique preuve d’un théorème.
temporary§1§Calcul intermédiaire§polynôme, pivot, matrice§On range les brouillons avant le résultat.§Objets internes avec provenance de protocole ; leur domaine est documenté.§Leur taille ne mesure pas directement le progrès global.
obstruction§5§Obstacle§perte non contrôlée ou signe inconnu§La carte montre ce qui bloque vraiment.§Branches et collisions sont des problèmes de suivi ; positivité une obligation de forme ; coef complexe autre portée.§Le nouveau pont offre un autre chemin sans déclarer les problèmes antérieurs résolus.
parameter_family§5§Paramètres et quantificateurs§S>0 ; k≥0 ; c∈ℂ§Les boutons ont toutes leurs positions possibles.§La famille dense couvre k, la complexification couvre c, mais la loi de signe reste à démontrer.§Un échantillon de boutons ne représente pas toutes leurs positions.
last_invariant§5§Invariant ne signifie pas signe§δ_G/δ_B fixé par représentation§La balance garde sa réponse, même si elle penche.§Valeur conservée sous transformations du drapeau ; signe peut être positif ou négatif.§Trouver l’invariant est une étape ; trouver une loi positive de cet invariant en est une autre.
convention§1§Convention§première variable antilinéaire§Le carnet fixe dans quel sens lire les flèches.§Produit scalaire ∫f̄g ; corrélation diagonale et forme hermitienne cohérentes.§Si h_ij est défini avec conjugaison seconde, les indices de polarisation doivent être adaptés.
eigen_prefix§5§Spectres des préfixes§V₂⊂V₄⊂V₆⊂V₈§Chaque boîte garde les anciennes pièces.§Même famille, B normalisé ; λ_min ne peut augmenter lors d’une extension.§L’affichage numérique confirme une propriété structurelle mais n’est pas sa preuve.
computed_sign§5§Signe observé§λ_min numérique§La règle lit de quel côté est le résultat.§Sortie exploratoire arrondie, précision et contrôle croisé affichés.§Le signe est dit observé et non certifié tant que l’intervalle manque.
exact_bounds§5§Borne calculable requise§valeur explicite + preuve§La règle donne aussi sa boîte de sécurité.§Un théorème d’existence de constante doit devenir formule efficace pour les certificats.§Le mot compact à lui seul ne fournit pas la constante numérique.
finite_negative§5§Négativité possible à S fixé§κ(K_S)>1§Quelques corrections peuvent dépasser l’identité.§Seul un nombre fini de valeurs propres de K_S dépasse 1, chacune à multiplicité finie.§Les éliminer toutes reste exactement le travail de signe.
progressive_full§1§Dictionnaire évolutif§ajouter une fiche qualifiée§La langue grandit en gardant ses premières règles.§Nouvelle définition avec identifiant, provenance, domaine et garde ; éditions futures possibles.§V644 est une édition substantielle, pas l’inventaire certifié de chaque formule historique.
read_graph§1§Lire le graphe§chemin + conditions§La carte montre les clés manquantes.§Graphique des constructions acquises et obligations, zones d’intérêt explicitement reliées.§Une branche barrée ne barre pas les autres chemins.
symbolic_units§1§Les unités dans les calculs§[Gv]=A², [Bv]=A², [λ]=1§Les étiquettes se retrouvent de chaque côté.§Les coefficients v sont sans dimension si les f_i portent A ; dette Schur porte A².§L’étiquette A d’amplitude est distincte du coefficient A complexe des anciennes familles.
strict_psd§4§PSD et marge§G⪰0 versus G⪰cB§La balance tient ou garde une marge.§Première propriété admet directions nulles ; seconde impose c>0 dans la métrique B.§La seconde est impossible pour toute E_S avec B_H¹ ; la première reste ouverte.
log_growth§5§Croissance logarithmique§a(τ) comparable à log(2+|τ|)§Les rythmes rapides prennent un poids qui grandit doucement.§La série positive donne divergence ; comparaisons élémentaires donnent ordre logarithmique.§Les constantes d’une estimation effective doivent être écrites, pas remplacées par le mot comparable.
compactness_scope§5§Compactité locale en support§j_S compact pour S fixé§La valise fermée limite où le dessin peut partir.§Support serré et poids Fourier divergent donnent injection compacte.§Sur toute la droite sans support fixé, translations empêchent cette compactité.
bridge_dictionary§5§Mots qui font deux choses§P ; parité ; R ; Schur§Une clé agit sur deux attaches.§Coups doubles prouvés ou contrats identifiés, statut de chaque usage distinct.§Schur fournit réduction+budget de couplage sous hypothèse de queue positive, pas le signe automatique.
future_order§5§Ordre des prochaines actions§queue→couplages→loi tous S§Le prochain pont a ses trois pièces.§D'abord borne η calculable, ensuite Schur effectif, enfin preuve arithmétique couvrante.§Ce plan accompagne les résultats V644 ; il n’est pas une conclusion scientifique.
contraction_multiplier§5§Budget de contraction§a(τ/λ)≤λ^(−2)a(τ)§Rétrécir peut rendre les rythmes plus rapides, mais leur coût est borné.§Termes positifs de la série de a donnent l’inégalité pour 0<λ≤1 ; continuité forte à1.§Ce budget ne préserve pas Q_W ni les moments.
arith_budget_units§5§Unités du budget§M_S sans dimension ; η sans dimension§Les petits tickets de coût portent la même règle.§x et support sans dimension, normes d’amplitude A ; Q et R unité E=A².§Un budget formel n’est pas une énergie positive physique.
chosen_metric§5§Choisir la bonne langue§Q_W représentée dans R§La règle écoute les glissements qui comptent.§La partie positive archimédienne crée la métrique, les termes L² deviennent compacts.§Ce choix réduit l’infini à une exception finie locale sans payer la preuve du signe.
community§5§Lecture externe ultérieure§soumission et revue§Le pont pourra être traversé par d’autres lecteurs.§Le dossier LaTeX est préparé ; aucun dépôt/publication externe réalisé sans instruction explicite.§L’exécution actuelle concerne les fichiers et le corpus, pas une annonce de résultat global.
source_register§1§Registre complet nommé§95 métaphores§Tous les mots imagés connus gardent leur fiche.§Extraction de toutes les lignes nommées du registre 20, avec ligne et dernière occurrence.§Cela ne couvre pas chaque image informelle présente ailleurs sans entrée nommée.
program_inventory§1§Index des programmes§fonctions et classes Python§Chaque outil a son adresse dans le carnet.§AST de tous fichiers .py analysables sous les trois dossiers actifs ; noms qualifiés, signatures, lignes.§Aucun comportement n’est inventé lorsqu’une docstring manque.
scope_archive§5§Archives conservées§preuves et certificats antérieurs§Les anciennes pierres restent à leur place.§Les fichiers historiques sont conservés dans le ZIP ; nouveaux résultats ajoutés sans réécrire leurs données.§Une correction documentaire actuelle ne modifie pas les anciens certificats gelés.
error_j§5§Injection et erreur de queue§η_N=||(I−Π_N)j_S||§Le dessin entier dépasse de moins en moins sa petite boîte.§Pour projections appropriées et compact j_S, η_N→0 ; contrat de queue ensuite.§Une projection cible L² doit être reliée au complément R choisi avant Schur.
polynomial_basis§4§Base monomiale§f₀,…,f_(n−1)§On empile les briques dans un ordre simple.§Famille indépendante, exacte, commode pour corrélations ; Gram de plus en plus conditionné.§Une base orthogonalisée peut améliorer le calcul sans changer l’inertie.
q_real§4§Forme et ordre§Q_W(f)∈ℝ§La balance rend une lecture sur une règle droite.§Hermitianité de Q garantit réalité même pour f complexe.§Réalité n’est pas positivité.
constant_control§5§Dépendance des constantes§C(S), M_S, η(S,N)§Chaque ticket dit de quelle boîte il vient.§Les estimations sont écrites avec paramètres visibles.§Cacher S derrière une lettre C ne construit pas une preuve globale.
dialogue§1§Thèse et objection§construction ↔ garde§Deux lecteurs essaient la même clé en sens opposés.§Workflow interne pour proposer une preuve et chercher ce qui la casse.§Accord des lecteurs ne remplace pas hypothèses, preuve et vérification externe.
critical_line§2§Ligne critique§Re s=1/2§La porte finale ressemble à une ligne dans un plan.§Ensemble vertical où RH place tous les zéros non triviaux.§La symétrie autour de cette ligne n’impose pas que les zéros y restent.
gamma_complete§2§Complétion archimédienne§π^(−s/2)Γ(s/2)§On ajoute la partie qui rend le miroir exact.§Facteur de la zêta complétée ; source des contributions archimédiennes.§Supprimer la complétion change la forme explicite et son critère.
test_family_arith§5§Tests construits sans zéros§fS,k=PψS,k§Les briques viennent des fonctions, pas de notes déjà connues.§Matrices utilisent primes, logs et noyau archimédien, aucun fichier de zéros.§Cela évite une dépendance de construction ; ne prouve pas le signe.
operator_transform§5§Transport d’opérateur§A↦UAU^(−1) si U unitaire§La même machine change de pièce avec sa règle.§Spectre et propriétés unitaires conservés pour domaines correctement transportés.§Changer la métrique de Riesz H¹→R n’est pas automatiquement cette opération.
cover_nb§5§Pont NB avec garde§densité NB ⇔ RH§Les dessins NB ont leur propre porte globale.§Régulariser toute entrée L² donne un cœur ; régulariser seulement NB exige sa densité ou un autre argument.§Cette porte ne peut pas servir de prémisse gratuite à RH.
norm_equiv§4§Équivalence des normes du moule§1/16||ψ||H³²≤||Pψ||H¹²≤3/2||ψ||H³²§Le moule fournit deux règles qui ne se contredisent pas.§Constantes exactes et indépendantes de S avec norme H³ somme des dérivées.§Ces constantes ne sont pas des marges positives de Q_W.
finite_schur§5§Schur fini versus effectif§δ_prefix versus G_eff§Une attache finie ne contient pas encore toutes les autres.§Dettes V₂→V₄… calculées dans notre famille ; Schur effectif tient compte du complément infini.§Les dettes numériques du préfixe ne remplacent pas le contrat de queue.
syllable§1§Syllabe de la grammaire§objet, relation, action§Les traits s’assemblent avec une règle.§Une fiche nomme l’objet ; une relation dit ce qui tient ; un opérateur transforme avec garde.§La nouvelle langue ne supprime pas les notations mathématiques usuelles.
schematic§1§Schéma fidèle§graphe des obligations§Le dessin garde les ponts ouverts visibles.§Diagramme précis de dépendances, pas image générée spéculative.§Une flèche doit porter son statut, sinon elle serait ambiguë.
publication_ready§5§Article préparé§PDF + LaTeX + sources§Le texte devient un paquet que l’on peut relire.§Documents 68 et 69 compilés et inspectés ; bibliographie et portée explicites.§Prêt à relire ne signifie pas accepté ou publié à l’extérieur.
language_goal§5§Langue utile§traduit sans cacher la perte§Les nouveaux mots servent à fabriquer des ponts.§Le critère d’utilité est un contrat vérifiable avec un double gain réel.§Une langue seule ne résout pas le problème ; les lemmes et calculs lui donnent prise.
infinite_tail§5§Infini contrôlé§queue coercive après V fini§La grande boîte restante reste attachée mais surveillée.§Conséquence de I−compact à S fixé ; permet une réduction conditionnelle exacte.§On ne jette pas la queue ; on la borne puis intègre son couplage par Schur.
actual_open§5§Prochain résultat à obtenir§borne η et signe G_eff§La prochaine clé a une forme précise.§Passer de réduction structurelle à certificat effectif ; puis loi arithmétique tous supports.§La tâche V644 fournit fondation, résultats finis et protocole, sans feindre ce résultat.
one_operator§1§Un seul geste bien nommé§P: H₀³→E_S§Une petite clé peut ouvrir deux portes.§Lemme d’isomorphisme et identité de norme sont le premier double gain.§La taille du pas n’est pas son importance conceptuelle.
dictionary_find§1§Chercher un mot§nom, symbole, image, garde§Le carnet retrouve le jouet même avec un autre nom.§Recherche sans accent, filtres par niveau/famille, fiche sélectionnable.§Les recherches ne fabriquent pas une définition manquante.
desire_vs_fact§5§But et fait§recherché ≠ acquis§Une porte dessinée n’est pas encore ouverte.§Les statuts montrent ce qui est prouvé, calculé, prévu ou encore ouvert.§Aucun désir de positivité n’est incorporé au statut des résultats.
matrix_basis_change§4§Transformation des coordonnées§c_old=C c_new§Le puzzle garde le même dessin avec d’autres pièces.§G_new=C*G_oldC, B_new=C*B_oldC ; unité des coefficients inchangée.§La formule inverse v′=C^(−1)v ne doit pas être confondue avec C v.
test_complex_span§5§Amplitude complexe de la famille§c∈ℂ^n§Chaque pièce peut avoir une petite flèche.§Matrice réelle hermitienne couvre toutes les combinaisons complexes de son sous-espace.§N’affirme pas résolution de A arbitraire dans toutes les constructions du corpus.
quote_guard§1§Citation et ancrage§source, section, portée§Le mot garde le livre où l’on peut le vérifier.§Références humaines dans les PDF, sources locales dans les fiches.§Une attribution précise n’est pas une preuve de transfert entre domaines.
parametric_equation§5§Équation paramétrique§F(z,t,A)=0§Le chemin dépend de plusieurs boutons.§Suivi local par fonction implicite si dérivée z non nulle ; collisions exigent préparation.§Les règles d’une famille ne se transportent pas sans contrat à une autre.
unknown_branch§5§Passage de branche ouvert§qui est qui après collision ?§Deux chemins ont besoin d’étiquettes.§Question d’identification et continuation globale des zéros ; données locales insuffisantes.§La voie Q_W peut éviter ce suivi pour RH, sans le résoudre pour lui-même.
width_cutoff§4§Plafond par diamètre§X=⌊e^D⌋§La largeur de la valise fixe la liste de tours.§D=2S pour notre famille, cutoff exact par Taylor.§Une translation ne change pas D ; élargir artificiellement la fenêtre peut seulement augmenter un budget.
load_budget§5§Budget maximal des premiers§2Σlog p·p^(−m/2)§On compte le poids total avant d’essayer le signe.§Majoration absolue par Cauchy–Schwarz et finitude de liste.§Le budget perd les cancellations ; le Schur exact doit conserver les interactions.
invariant_scope§5§Groupe d’un invariant§transformations autorisées§La clé tient pour certains gestes seulement.§Phase/translation pour h ; congruence pour inertie ; transformations du drapeau pour dette.§« Invariant global » sans groupe ni domaine serait ambigu.
topology§3§Topologie de convergence§L², H¹, R§Trois règles voient des détails différents.§Normes définissent proximité et fermeture ; les passages gardent leurs budgets.§Une suite peut être proche pour une règle et éloignée pour l’autre.
no_magic§1§Garde de la langue§nom imagé + définition exacte§Un joli mot ne remplace pas le dessin.§Chaque image du noyau est accompagnée d’une relation canonique et d’une limite.§Les opérateurs hérités restent historiques tant que leur ancrage ne fournit pas un contrat complet.
step_result§5§Résultat de cette étape§pont de métrique + famille + grammaire§On construit de vrais passages avec leur carnet.§L1–L7, diagnostics finis, dictionnaire et protocole de prochaine réduction effective.§La recherche RH continue ; la conclusion globale reste ouverte.
test_callable§1§Fonction du programme§def nom(args)§Une petite recette avec des entrées.§Déclaration Python indexée avec contexte lexical ; signatures et docstrings consultables.§Une recette technique peut traiter fichiers ou HTML sans rien affirmer sur RH.
g_function§5§Fonction logarithmique G(s)§G(s)=Log F(s) selon archive§Un carnet mesure la rotation d’une fonction.§Définition dépendant d’un domaine sans zéros et d’une branche ; voir source historique locale.§Ne pas l’identifier au Gram ni la considérer globalement définie à travers tous les zéros.
surface_virtual§5§Surface virtuelle§axiomes formels du corpus§Un dessin ressemble à un terrain avant d’en être un.§Construction comparative/virtuelle des documents46–48, dont domaine et axiomes doivent être repris.§Aucune variété géométrique de ζ construite par cette seule analogie.
spectral_gap_tail§5§Marge de la queue R§1−M_Sη²>0§Le reste de la balance garde une marge.§Minoration conditionnelle sur V⊥_R à S fixé, grâce à compactité et budget.§Elle n’est pas une marge sur toute X_S et n’est pas encore certifiée pour un V explicite.
closure_proof§5§Preuve de fermeture de R§multiplicateur 1+a§Les dessins proches restent dans la même règle.§R est norme Hilbert pondérée Fourier ; contraintes support/moments fermées.§La norme est construite sans signe global de Q_W.
cutoff_integer§4§Liste des puissances exacte§sieve + tours p^m§On fait la liste de toutes les briques autorisées.§Crible entier et multiplication jusqu’à X certifié, aucune donnée de zéros.§Un test de primalité ou cutoff flottant non encadré exigerait une autre garde.
finite_q_pos§5§Positivité observée§λ_min(S,n)>0 numériquement§Les petits dessins testés tiennent.§Le tableau de l’article donne les minima réels calculés et la dette du drapeau.§Cette phrase se limite aux paramètres et à l’erreur exploratoire.
hermitian_real_basis§4§Base réelle et coefficients complexes§G réel symétrique§La table réelle répond aussi aux petites flèches.§c*G c = uᵀGu+vᵀGv pour c=u+iv ; même critère PSD.§Un autre paramètre complexe peut changer les coefficients de G ; il faut l’examiner séparément.
conservation§1§Conserver une relation§mêmes attaches après geste§La valise garde certaines attaches.§Le dictionnaire cite les relations exactement conservées, budgets des autres.§Il n’y a pas conservation de toute information par toute transformation.
method_future§5§Suite déjà définie§certifier la queue et ses couplages§La prochaine partie a une recette.§Nouveau protocole précis dans document68 ; arrêt indéterminé si bornes insuffisantes.§Aucune certitude de succès avant exécution.
proof_level§1§Niveaux d’explication§image ; objet ; formule ; preuve§On monte l’escalier des mots.§Image au premier niveau, détail exact disponible sans cacher la garde.§Le lecteur peut comprendre l’image sans recevoir une fausse preuve.
same_thing§1§Même chose avec conditions§équivalence sous contrat§Deux portes peuvent vraiment mener au même endroit.§Identité ou équivalence doit être écrite avec domaine et quantificateurs.§Énergie physique et forme arithmétique partagent des unités formelles possibles, pas une positivité automatique.
prime_arch_balance§5§Balance arithmétique centrale§Q_W=R−B_S§Les premiers et le miroir tirent sur une règle indépendante.§Formule exacte ; B_S continu dans L² et compact après injection.§Le signe de I−K reste la dernière question arithmétique.
infinite_positive§5§Positivité globale§I−K_S⪰0 pour tous S§Toutes les corrections restent sous l’identité.§Formulation dans R équivalente au signe sur le cœur, puis RH.§Compactité montre exceptions possibles finies localement, pas leur élimination.
critical_double§5§Zéro critique double§F(ρ)=F′(ρ)=0, Re ρ=1/2§La note touche la ligne deux fois.§Question de multiplicité/collision avec jets certifiés locaux selon la famille.§RH n’impose pas la simplicité des zéros ; ne pas confondre ces deux buts.
rh_simple§2§RH et simplicité§RH ≠ tous les zéros simples§La ligne et les doubles notes sont deux règles.§RH porte sur la partie réelle ; conjecture de simplicité est plus forte et distincte.§Résoudre une collision de zéros n’est pas nécessairement nécessaire à prouver RH par un critère de forme.
goal_decomposition§5§Décomposer le but§domaine + queue + Schur + tous S§La porte finale a quatre attaches.§Les deux premières sont structurelles ici ; effectivité/signe global restent manquants.§Une carte rend l’inconnu précis sans le résoudre.
new_grammar§1§Langue des passages§moule, valise, portée, puzzle, balance§Des mots courts nomment les gestes.§Vocabulaire nouveau relié aux notations classiques : P, U, Fourier/Mellin, C et Schur.§Cette langue ne remplace pas la littérature ; elle permet de suivre les contrats.
game_bad§1§Coup interdit§moduler f sans corriger les moments§Une clé rentre dans la mauvaise boîte.§Le validateur explique exactement la relation perdue.§Interdit dans ce contrat ne signifie pas que l’opérateur est mathématiquement illégitime ailleurs.
game_good§1§Coup autorisé§phase commune et translation§La valise garde son dessin et ses attaches.§Contrats exacts avec fenêtre et relations conservées.§Si le système ne représente pas une hypothèse, sa validation reste partielle.
translation_head§5§Traduire sans petit plafond§passer au domaine et au spectre§Une nouvelle règle voit l’infini autrement.§Pont R : structure I−compact et Schur effectif plutôt qu’extension seule de n.§Les calculs n≤8 illustrent cette construction ; ils n’en sont pas la justification.
effective_bound§5§Effectivité recherchée§N(S), η(S,N), résolvante§La recette doit dire combien de pièces garder.§Objectif du prochain protocole, avec coefficients et bornes calculables.§L’existence abstraite de N n’est pas encore cette recette.
proof_boundary§3§Traces pour l’isomorphisme§ψ=ψ′=ψ″=0 aux bords§Le moule ferme correctement chaque attache.§Deux moments de f assurent ψ et ψ′ à droite ; f trace0 assure ψ″.§L’argument doit inclure la régularité H³ et la distribution sans masses au bord.
arch_formula§4§Deux normalisations de l’archimédien§Q_arch=E_arch−C₀||f||²§Deux lectures du même plateau.§Identité démontrée V643 ; quadratures comparées V644 avec stabilisation de h(x)−h(0).§Les deux lectures peuvent partager une erreur de code ; les identités exactes fournissent un contrôle complémentaire.
term_t2§4§Deuxième jet de corrélation§2h(0)−h(t)−h(−t)=t²||f′||²+o(t²)§Le petit glissement commence au carré du pas.§Coefficients exacts des corrélations polynomiales ; stabilité près du noyau singulier.§Le reste dépend de régularité et intervalle ; ne pas extrapoler au-delà du support.
union_density§5§Réunion dense§∪_n span(f₀,…,f_(n−1))§Toutes les petites boîtes peuvent approcher la grande.§Densité démontrée à S fixé dans H¹, puis dans R via cœur et continuité.§Il faut les normes et la continuité indiquées avant de transporter un signe.
step_all_functions§5§Fonctions utilisées dans l’expérience§P, w, h, arch, primes, eig, Schur§Chaque pièce du calcul a sa fiche.§Entrées mathématiques explicitées et implémentations indexées ; pas de données de zéros.§La couverture du calcul V644 est complète ; la couverture de chaque formule historique ne l’est pas revendiquée.
nonzero§1§Non nul§c≠0§Le jouet existe encore.§Condition d’inversibilité pour mise à l’échelle d’un vecteur et changement de base.§c=0 détruit une direction et peut perdre une information de signe.
truthful_unknown§1§Dire ce qui manque§ouvert avec témoin de réussite§La carte garde la porte vide.§Liste explicite des obligations et prochaine expérience ; résultats sûrs seulement là où la preuve porte.§Le langage nouveau doit rendre l’inconnu visible, pas le masquer.
support_frequency§5§Double contrôle support/fréquence§compactité j_S§La valise ne part pas au loin et les rythmes rapides pèsent.§Support fixe contrôle les translations ; a→∞ contrôle queue Fourier ; ensemble donne compacité.§Chacun seul ne suffit pas pour une injection globale compacte.
graph_complete§5§Graphe de ce programme§contrats actuels, pas tous chemins possibles§La carte décrit notre terrain exploré.§Documents68–69 et registre relient preuves, expériences et obligations actuelles.§Impossible d’affirmer que toutes les voies de RH ont été inventoriées.
method_compare§5§Comparaison des voies§H¹ no-go ; R réduction finie§Deux règles donnent deux lectures précises.§L’échec de coercivité H¹ motive la métrique naturelle archimédienne.§Cela fait évoluer la structure du problème sans trancher le signe global.
publication_scope§5§Portée du texte LaTeX§rapport de recherche, preuves auxiliaires§Le carnet peut être partagé pour examen.§Forme soignée avec assertions et limites séparées ; fichiers locaux livrés.§Aucune annonce de résolution, aucun dépôt externe effectué.
energy_symbol§1§Étiquette E fictive§E=A_amp²§L’énergie du carnet est une unité de carré.§A_amp unité d’amplitude, distincte du coefficient complexe A ; toutes formes portent E.§La possibilité d’unité ne suffit pas à écrire E≥0 pour Q_W.
logical_not§1§Négation d’une route§¬(∃c>0 coercifH¹)§On barre une clé précise.§Proposition no-go démontrée pour cette norme et domaine.§Ne pas transformer cette négation en « aucune preuve possible ».
invertibility§4§Inverse§A^(−1)A=I§La machine sait refaire le chemin à l’envers.§Exige bijection et bon domaine ; en dimension finie det A≠0.§Pour queue R, l’inverse exige la marge >0 avant Schur.
intro_schur§1§Attaches dans une balance§δ=a−c*G^(−1)c§Le nouveau jouet paie ce qu’il tire sur les anciens.§Image du Schur sous G>0, dérivation complète dans article68.§La formule sans hypothèses serait trompeuse.
progress_bridge§5§Progrès conceptuel vérifiable§même forme, domaine mieux adapté§La nouvelle règle organise mieux les mêmes pièces.§Un vrai pont modifie la structure du problème : compacte→I−compact, queue positive après dimension finie.§Il ne suffit pas de changer les mots ; les preuves L5–L7 justifient ce changement.
remainder_positive§4§Termes positifs du multiplicateur§a(τ)=Σ≥0§Les petites briques ne s’annulent pas ici.§Tonelli et convergence monotone valides pour a et w.§Q_pr ne partage pas cette positivité terme à terme.
final_open_exact§5§Ouverture précise restante§κ_max(K_S)≤1 pour tous S§La correction ne doit jamais dépasser la règle.§Équivalent au signe dans R ; Schur offre réduction locale finie si queue contrôlée.§La compacité ne donne pas cette borne de la plus grande valeur propre.
family_data§5§Données et statut§JSON avec protocole et valeurs§Le carnet garde les lectures et leurs règles.§Toutes matrices, préfixes, checks, plafond exact et empreinte du protocole sont archivés.§Le JSON distingue exact et numérique ; il ne porte pas de certificat spectral validé.
dictionary_register§1§Deux sortes de mots§math:… et metaphor:…§Les machines et les images ont des tiroirs séparés.§Entrées mathématiques pédagogiques ; métaphores héritées exactes, avec garde originale.§Une entrée de métaphore n’est pas promue en opérateur par extraction automatique.
bridge_scope_end§5§Bilan de V644§exécuté, démontré, encore ouvert§Le carnet dit ce que chaque pont porte.§Construction dense, nouvelles structures analytiques, calculs finis et langue testable.§La loi arithmétique globale reste le but suivant.
'''
def core():
    rows=[]
    for line in CORE.strip().splitlines():
        fields=line.split('§');assert len(fields)==7,line
        i,lv,name,symbol,image,exact,guard=fields
        rows.append(dict(id='math:'+i,level=int(lv),kind='math',name=name,symbol=symbol,image=image,exact=exact,guard=guard,
            status='définition pédagogique ; voir portée précise dans ancrage et garde',
            source='Documents 67–68 et noyau du corpus ; définition locale explicitée dans cette fiche'))
    # Keep distinct mathematical objects; avoid repeating the same guard as many entries.
    extra={'spectral_essential','finite_rank','neumann','conditioned','reflection','reflection_metric','lowfreq','contraction','contraction_multiplier','exact_metric','complex_inner','realification','translation_defect','integration_parts','parity_flag','moment_matrix','correlation_poly','endpoint_jet','support_diameter','dual','distribution','complex_phase_proof','kernel_series','thin_tail','strict_psd','log_growth','inclusion','inequality_cs','product_rule','identity','floor','factorial','tail_taylor','codimension','linear','quadratic','operator_transform','norm_equiv','finite_minimum','critical_line','rh_simple','critical_double','periodicity','absolute_conv','branch_log','g_function','surface_virtual','functional_equation','analytic_cont','realpart','transpose','power_prime','arctan','energy_arch','cross_term','partition','proper_metric'}
    rows=rows[:145]+[r for r in rows[145:] if r['id'].split(':',1)[1] in extra]
    new=r'''
convolution_algebra§3§Algèbre de convolution§A=Cc∞(ℝ), opération *§Deux dessins s’assemblent en glissant.§Algèbre commutative associative, sans unité parmi les fonctions ; ℒ_exp(f*g)=ℒ_exp(f)ℒ_exp(g).§Le produit ordinaire est une autre multiplication.
exponential_transform§3§Portée exponentielle§ℒ_exp f(z)=∫e^(zx)f(x)dx§Le dessin devient une partition de notes.§Fonction entière pour f compact ; variable z distincte de s Mellin, z=s−1/2.§Les zéros en ±1/2 sont contraintes auxiliaires, pas zéros de ζ.
jet_ideals§4§Idéaux de jets admissibles§I_r={f∈A : ∫x^j e^(±x/2)f=0, j<r}§Plus de balances sont attachées aux deux portes.§Idéaux de convolution ; I₀=A ; I_r*I_s⊂I_(r+s), somme dans I_min(r,s).§Les unités d’amplitude se multiplient ; convolution n’implique pas positivité de Q_W.
grammar_arith§4§Arithmétique des fonctions§addition, scalaire, produit, convolution§Quatre gestes ont chacun leur règle de montage.§Somme/scalaire conservent I_r ; convolution additionne les ordres garantis ; produit ordinaire peut perdre I₁.§Ni D_x ni U_a ne sont des homomorphismes de convolution dans le sens naïf.
derivation_convolution§4§Dérivation pour convolution§x(f*g)=(xf)*g+f*(xg)§Le bouton position se partage entre deux dessins.§Multiplication par x est une dérivation de l’algèbre de convolution ; D_x(f*g)=Df*g=f*Dg.§D_x est dérivation du produit ordinaire, pas de la convolution.
p_jet_ladder§4§Échelle de jets par P§ℒ_exp(Pf)=(z²−1/4)ℒ_exp f§Le moule ferme une balance de plus à chaque porte.§P:I_r→I_(r+1) sur graines Cc∞ ; x:I_(r+1)→I_r ; D_x:I_r→I_r.§Ordre garanti au moins ; certaines annulations supplémentaires peuvent apparaître.
typed_logic§5§Logique des domaines§Γ⊢f : A(S,r,u)§La phrase dit quelle boîte le dessin peut atteindre.§S support, r ordre garanti de jets, u degré d’unité A ; règles sound dans A, preuves L8.§Pas un système complet décidant toute identité ou la vérité de RH.
moment_tail§5§Queue de moments ordinaires§Y_N={∫x^j f=0, 0≤j≤N}§Les rythmes lents deviennent minuscules après plusieurs balances.§Codimension N+1 dans X_S ; queue positive effective via Taylor Fourier et budget L².§Distincte des idéaux I_r, qui utilisent les poids e^(±x/2).
tail_epsilon§5§Borne explicite de queue§ε_N(T)=2(ST)^(2N+3)/[π(2N+3)²((N+1)!)²]§On encadre les rythmes lents dans une petite boîte.§Pour Y_N, énergie Fourier dans [−T,T]≤ε_N||f||₂² ; si ε<1, ||f||₂²≤R/[(1−ε)r(T)].§Borne prouvée, mais choisir des paramètres grossiers peut donner une tête astronomique.
integer_tail§5§Contrat de queue entier§Lbar=8+2M, T=2^(8Lbar), q=ceil(6ST)§Une recette ferme la queue avec des comptes entiers.§Pour Y_(q−1), Q_W≥R/(1+2Lbar) ; M nombre exact de puissances premières actives.§La tête a dimension q ; elle n’a pas été calculée dans cette expérience.
neumann_error§5§Erreur de dette par Neumann§reste≤η^(m+1)/(1−η)§Les corrections restantes ont un ticket de taille.§η=L_S/[(1−ε)r(T)]<1 borne le compact comprimé sur la queue ; budget inverse et Schur prouvés.§Le solveur des actions/projections doit encore être certifié.
nonpreserving_product§3§Produit qui perd les moments§ℓ±(f²)>0 pour f réel non nul§Deux dessins autorisés peuvent fabriquer un dessin interdit.§Si f∈I₁ réel non nul, f²≥0 et poids exponentiels positifs : produit hors I₁.§La convolution f*f reste admissible et renforce les annulations.
origin_jets§4§Jets ordinaires en zéro§ℒ_exp^(j)f(0)=∫x^j f(x)dx§Une nouvelle balance lit les rythmes lents.§L’annulation d’ordre q en 0 définit la queue Y_(q−1) ; D_x gagne un ordre en 0 et P le conserve.§Ce point du test n’est pas un zéro critique de ζ.
quotient_jets§4§Quotient de jets§A/I_r ≃ ℂ[ε]/(ε^r) ⊕ ℂ[ε]/(ε^r)§Deux petits carnets gardent les premiers traits du dessin.§Jets normalisés ℒ_exp^(j)f(±1/2)/j! ; produit de coefficients tronqué ; codimension 2r.§Le quotient oublie tous les autres traits ; r>1 ne couvre pas tous les tests de I₁.
ideal§4§Idéal de convolution§I_r*A⊂I_r§Une porte fermée reste fermée quand on colle un autre dessin.§Sous-espace stable sous convolution par toute graine ; somme conserve l’ordre minimal garanti.§Idéal ici se rapporte à convolution, pas au produit ordinaire.
truncated_polynomial§4§Polynôme tronqué§ℂ[ε]/(ε^r)§Un carnet efface tous les traits trop hauts.§Addition coefficient par coefficient et produit Cauchy avec ε^r=0 ; représentation exacte d’un jet d’ordre r−1.§Ce ε formel est distinct de l’erreur ε_N(T).
head_riesz§5§Représentant Riesz des moments§⟨h_j,f⟩R=∫x^j f(x)dx§Un capteur devient un dessin dans la bonne règle.§Les h_j engendrent F_N=Y_N⊥_R ; codimension N+1 ; solveur et résidus à certifier.§Cette tête diffère du préfixe polynomial brut utilisé par les matrices exploratoires.
derivative_origin§4§Deux moules compatibles§D_x^q P^r ψ∈I_r∩Y_(q−1)§Deux clés ferment les portes et les rythmes lents.§D_x et P commutent ; ℒ_exp multiplie par (−z)^q(z²−1/4)^r ; support contenu dans celui de la graine.§La construction peut être dans une queue positive sans couvrir la tête où le signe est inconnu.
'''
    for line in new.strip().splitlines():
        i,lv,name,symbol,image,exact,guard=line.split('§')
        rows.append(dict(id='math:'+i,level=int(lv),kind='math',name=name,symbol=symbol,image=image,exact=exact,guard=guard,status='relation démontrée dans V644, L6–L8',source='3_Preuves_et_calculs/preuves/V644_LANGUE_ET_DOMAINES.md ; L6–L8'))
    proved={'p_operator','p_inverse','seed','density','exact_metric','norm_equiv','riesz_h1','riesz_r','external_r','x_domain','a_multiplier','schur_ratio','parity','compact','finite_reduction','neumann','matrix_l2_bound'}
    for r in rows:
        key=r['id'].split(':',1)[1]
        if key in proved:r.update(status='preuve auxiliaire interne ; portée et conditions dans L1–L7',source='Document 68 ; V644_LANGUE_ET_DOMAINES.md, L1–L7')
        if key=='tail':r['exact']='Une queue coercive explicite est construite par moments ordinaires ; le taux pour la queue orthogonale de la base brute f_k reste à établir.';r['guard']='Ne pas identifier la queue de moments avec le complément de span(f_k).'
        if key=='schur_tail_gate':r['exact']='La queue de moments Y_N satisfait la condition par la borne ε_N(T) ; existence et paramètres explicites prouvés.'
    assert len({r['id'] for r in rows})==len(rows)
    return rows
def metaphors():
    p=P/'20_Registre_metaphores_V6.md';ops={};hdr=None;section=''
    for num,line in enumerate(p.read_text(encoding='utf-8-sig').splitlines(),1):
        if line.startswith('## '):section=line[3:]
        if line.startswith('| Nom'):hdr=[s.strip() for s in line.strip().strip('|').split(' | ')]
        if line.startswith('| **') and hdr:
            cells=[s.strip() for s in line.strip().strip('|').split(' | ')];assert len(cells)==len(hdr)
            raw=dict(zip(hdr,cells));name=cells[0].replace('**','')
            def get(*names):return next((raw[x].replace('**','') for x in names if raw.get(x)), '')
            status=' ; '.join(v.replace('**','') for k,v in raw.items() if 'Statut' in k) or 'statut non explicité dans cette ligne historique'
            ops[name]=dict(id='metaphor:'+name,level=5,kind='metaphor',name=name,symbol=get('Énoncé exact','Objet exact / ancrage'),
                image=get('Image','Image mentale') or 'Image historique à lire avec son ancrage ci-dessous.',
                exact=get('Énoncé exact','Objet exact / ancrage'),guard=get("Où l'image casse","Où l’image casse",'Correspondance interdite'),
                authorized=get('Correspondance autorisée'),status='hérité du registre : '+status,
                source='1_Presentation/20_Registre_metaphores_V6.md:'+str(num)+' ; '+section,raw=raw)
    assert len(ops)==95
    return list(ops.values())
def code_inventory():
    out=[];errors=[]
    for folder in ['2_Methode','3_Preuves_et_calculs/src','3_Preuves_et_calculs/scripts']:
      for p in sorted((ROOT/folder).rglob('*.py')):
        try:t=ast.parse(p.read_text(encoding='utf-8-sig'))
        except Exception as e:errors.append(dict(path=str(p.relative_to(ROOT)),error=str(e)));continue
        def walk(node,ctx=''):
            for a in ast.iter_child_nodes(node):
                if isinstance(a,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
                    q=(ctx+'.' if ctx else '')+a.name
                    out.append(dict(path=str(p.relative_to(ROOT)),line=a.lineno,name=q,kind='class' if isinstance(a,ast.ClassDef) else 'function',
                        signature=(ast.unparse(a.args) if not isinstance(a,ast.ClassDef) else ''),docstring=ast.get_docstring(a) or '',
                        explanation_status='docstring source' if ast.get_docstring(a) else 'pas de docstring ; comportement non inféré'))
                    walk(a,q)
                else:walk(a,ctx)
        walk(t)
    return dict(entries=out,parse_errors=errors,file_count=len(set(x['path'] for x in out)))
def main():
    data=dict(version='V6.44',scope='Noyau pédagogique explicite + tous les 95 noms du registre ; pas une désambiguïsation exhaustive des symboles de chaque archive',entries=core()+metaphors())
    (D/'v644_dictionnaire.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    inventory=code_inventory();(D/'v644_index_fonctions.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2)+'\n')
    with (D/'v644_index_fonctions.csv').open('w',newline='',encoding='utf-8-sig') as f:
        fields=['path','line','name','kind','signature','docstring','explanation_status'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(inventory['entries'])
    print(len(core()),'fiches mathématiques;',len(metaphors()),'métaphores;',len(inventory['entries']),'déclarations techniques;',len(inventory['parse_errors']),'erreurs AST')
if __name__=='__main__':main()
